insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C269', 'Mejorar las condiciones laborales del personal de EDME (duchas y vestuarios)', 'El personal de EDME no cuenta con duchas y tiene vestuarios y dormitorios de portería en mal estado. Instalar duchas y mejorar los vestuarios y dormitorios para dar condiciones dignas a los trabajadores.', 16, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Predio de EDME, Bajo Llojeta, La Paz', '-16.5259365,-68.1224885', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C268', 'Implementar el sistema predictivo de repuestos (CRM) y subir el sistema Maresto a la nube', 'Implementar un sistema predictivo de repuestos y mantenimiento (CRM) a partir del uso histórico de la maquinaria, y subir el sistema propio ''Maresto'' a la nube con alertas, notificaciones e IA.', 16, 'EJE-03', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Predio de EDME, Bajo Llojeta, La Paz', '-16.5259365,-68.1224885', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C267', 'Habilitar el surtidor propio y el tanque pulmón de EDME', 'EDME tiene un mini surtidor y un tanque pulmón heredados sin instalar. Habilitar el surtidor propio y el tanque pulmón para no depender de compras por partes de combustible y optimizar la operación.', 16, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Predio de EDME, Bajo Llojeta, La Paz', '-16.5259365,-68.1224885', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C266', 'Regularizar el derecho propietario e intervenir el deslizamiento del predio de EDME', 'El predio de EDME (Bajo Llojeta) tiene tenedores sin título (derecho propietario sin regularizar) y una falla activa de deslizamiento que mueve el terreno. Regularizar el derecho propietario mediante análisis de catastro e intervenir el riesgo de deslizamiento mejorando la malla de contención.', 16, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-11-30', 'Territorio', 'Predio de EDME, Bajo Llojeta, La Paz', '-16.5259365,-68.1224885', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C265', 'Dar de baja el inventario y repuestos obsoletos del almacén de EDME', 'El almacén heredado del GAMLP al nacer EDME (~Bs 4 millones) tiene repuestos de marcas que EDME no usa, con movimiento mínimo. Dar de baja el inventario/repuestos obsoletos y ofrecerlos a las entidades a las que sí les sirvan.', 16, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Predio de EDME, Bajo Llojeta, La Paz', '-16.5259365,-68.1224885', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C264', 'Auditar las contrataciones a terceros de EDME (~Bs 167 millones)', 'Se contrató a terceros por ~Bs 167 millones con empresas que solo aportaban papeles y subcontrataban (sin pagar a los ejecutores). Auditar cada contrato y cada pago de las contrataciones a terceros de EDME; no ejecutar pagos de procesos irregulares.', 3, 'EJE-01', 'Vigente', '🟢', 'Alta', '2026-09-15', 'Territorio', 'Predio de EDME, Bajo Llojeta, La Paz', '-16.5259365,-68.1224885', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C263', 'Reactivar y habilitar la maquinaria parada de EDME', 'Varios equipos de EDME están de baja por faltantes menores (llantas, botellones de tolva, muelles, fluidos). Rehabilitar y reactivar la maquinaria parada con esos repuestos para ponerla al servicio del municipio (limpieza de ríos, obras, recojo, emergencias) en lugar de tercerizar.', 16, 'EJE-01', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Predio de EDME, Bajo Llojeta, La Paz', '-16.5259365,-68.1224885', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C262', 'Atender las necesidades prioritarias del Colegio Agustín Aspiazu (tinglado y laboratorio)', 'En el Colegio Agustín Aspiazu (Sopocachi, ~1.000 estudiantes/turno), construir el tinglado/cubierta de la cancha (usada para educación física y actos, hoy sin cubierta) e implementar el laboratorio; revisar además la vía de evacuación y las gradas en mal estado.', 149, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Colegio Agustín Aspiazu, La Paz', '-16.5077689,-68.1294874', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C261', 'Programa integral de laboratorios y computación en las unidades educativas', 'Con la Secretaría/Dirección de Ciudad Inteligente, implementar un programa integral para dotar y reactivar laboratorios y salas de computación en las unidades educativas (hoy varios abandonados o sin equipar).', 58, 'EJE-03', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C260', 'Poner a disposición más de 1.200 becas para estudiantes de La Paz', 'Mediante convenios con universidades e institutos, poner a disposición más de 1.200 becas (universidades, inglés y gestiones para becas en el exterior). Los mecanismos y evaluaciones los definen las universidades; ningún funcionario municipal interviene en la adjudicación.', 61, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C259', 'Programa de seguridad vial escolar (señalización, cebras y voluntarios)', 'Ampliar la seguridad vial en los accesos a las unidades educativas: pintado de señalización horizontal (≈40% avanzado, meta 100%), acompañamiento de las cebras y voluntarios/adultos mayores con estipendio para el cruce en horarios de ingreso y salida.', 113, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C258', 'Asignar presupuesto específico para las unidades educativas desde la gestión 2027', 'Inscribir en el presupuesto un ítem específico para el mantenimiento de las unidades educativas, para no depender de las bolsas de las subalcaldías y hacer un trabajo integral y estructural.', 61, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-11-30', 'Territorio', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C257', 'Programa de mantenimiento integral de las 226 unidades educativas', 'Tras heredar presupuesto cero para mantenimiento educativo, se atendió ~60% (≈145 U.E.) con más de Bs 800.000 desde las subalcaldías (electricidad, agua, techos, baños, canaletas). Compromiso: continuar hasta el 100% con un despliegue de fin de año (proceso de ~2 meses en vacaciones finales) para dejar las 226 infraestructuras en condiciones.', 61, 'EJE-05', 'Vigente', '🟢', 'Alta', '2026-12-31', 'Territorio', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C256', 'Investigar el presunto avasallamiento de terreno del Parque de las Cebras (caso Sr. Chura)', 'Vecinos denuncian que un particular (Sr. Chura) presuntamente avasalló/se apropió de terreno del parque. Investigar el derecho propietario y el presunto avasallamiento del terreno del parque.', 17, NULL, 'Vigente', '🟢', 'Media', '2026-08-15', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C255', 'Ejecutar el mantenimiento integral del Parque de las Cebras', 'Mantenimiento integral del parque: áreas verdes y plantas, limpieza, mejora de juegos y campos deportivos, y reposición de la bandera deteriorada.', 149, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C254', 'Retirar o regularizar la caseta inactiva del Ministerio de Salud en el Parque de las Cebras', 'La caseta del Ministerio de Salud (concesión para personas con discapacidad) lleva ~12 años sin funcionar y sin autorización. Retirar o regularizar la caseta/concesión inactiva.', 17, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C253', 'Instalar césped sintético e iluminación en las canchas del Parque de las Cebras', 'Mejorar las canchas del parque instalando césped sintético e iluminación, con la condición de habilitar el uso para fútbol femenino.', 54, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C252', 'Reubicar o retirar los juegos en mal estado y las plantas mal ubicadas del Parque de las Cebras', 'Reubicar o retirar los juegos en mal estado y las plantas medicinales mal ubicadas, que dañan el pasto e infraestructura y generan riesgo.', 149, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-08-15', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C251', 'Habilitar la puerta principal del Parque de las Cebras', 'Hoy se ingresa al parque por una puerta lateral pese a existir puerta principal. Habilitar la puerta principal del parque.', 149, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-08-15', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C250', 'Retirar de inmediato los fierros sueltos, tapar huecos y asegurar cables en el Parque de las Cebras', 'Hay fierros/partes metálicas sueltas, huecos y cables al alcance de los niños que representan peligro inmediato. Retirar los fierros, tapar los huecos y asegurar los cables de inmediato.', 149, 'EJE-09', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C249', 'Conectar el servicio de agua del Parque de las Cebras (coordinación con EPSAS)', 'Al parque solo le falta la conexión de agua para riego y baños; se coordinó con EPSAS y quedó pendiente la conexión (cisterna 8:30–9:00). Concretar la conexión del servicio de agua del parque.', 149, 'EJE-07', 'Vigente', '🟡', 'Alta', '2026-08-08', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C248', 'Resolver el drenaje y construir el muro de contención en la caja matriz del Parque de las Cebras', 'En época de lluvias el parque se inunda: la mazamorra baja desde la parte alta y desde la caja matriz/cámara que colapsa e ingresa al parque. Construir el muro de contención en la caja matriz y elevar los bordillos ya trasladados para desviar y frenar el agua.', 149, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-10-31', 'Territorio', 'Parque de las Cebras, La Paz', '-16.5197597,-68.13227239999999', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C247', 'Rehabilitar los servicios de la zona afectada de Valle de las Flores (energía/alumbrado, vía y poste)', 'Los vecinos llevan cerca de un año sin energía eléctrica ni alumbrado público desde el evento (12-may). Rehabilitar la energía y el alumbrado, reponer la vía intervenida (perfilado, como estaba) y resolver el poste con los cables colgando (coordinar con DELAPAZ el tesado/reposición).', 152, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Valle de las Flores / Callapa (distrito 16), macrodistrito San Antonio, La Paz', '-17.479429,-68.35543799999999', NULL, 'Cita: «un año que nuestros vecinos han estado cortados de la energía eléctrica... sin alumbrado público»; «el poste con la carga está bajo, los cables parecen colgador de ropa».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C246', 'Ejecutar la Fase 2 de estabilización de Valle de las Flores (embovedado del río Quiswaras, drenaje pluvial y retiro de escombros)', 'Tras verificar la Fase 1, ejecutar la Fase 2: reconstruir el embovedado del río Quiswaras (hoy solo concreto ciclópeo sin estructura metálica, deteriorado por el movimiento), construir bocas de tormenta y canales para las aguas pluviales que bajan de la parte alta, y retirar el material/escombro desprendido que quedó sobre las viviendas antes de la época de lluvias.', 106, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-11-30', 'Territorio', 'Valle de las Flores / Callapa (distrito 16), macrodistrito San Antonio, La Paz', '-17.479429,-68.35543799999999', NULL, 'Cita: «el embovedado del Quiswaras solo con concreto, sin estructura metálica, se ha hecho pomada»; «necesitamos bocas de tormenta, canales para el agua»; «el retiro de esa tierra antes de que empiecen las lluvias».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C245', 'Verificar con inclinometría el resultado del proyecto de mitigación del deslizamiento de Valle de las Flores y esclarecer los cambios de alcance/presupuesto', 'El proyecto de mitigación del mega deslizamiento (pilotes de hasta 60 m + galería filtrante de 366 m, empresa Constec, ~Bs 100 M) debe comprobarse: verificar con inclinometría si el movimiento se detuvo (si funcionan los pilotes), y exigir los informes técnicos que justifiquen —no por presupuesto— la reducción de 60 a 55 pilotes y los cambios de presupuesto/plazo (85→75→60 M, sucesivas ampliaciones). Las casas siguen fracturándose: hay que confirmar que se protegió la vida antes de avanzar.', 106, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Valle de las Flores / Callapa (distrito 16), macrodistrito San Antonio, La Paz', '-17.479429,-68.35543799999999', NULL, 'Cita: «necesito un informe técnico de por qué de 60 a 55, que no sea presupuestario»; «tres perforaciones con inclinómetro a 54 m para ver si están funcionando los pilotes, si sigue el movimiento o no».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C244', 'Diagnosticar y reactivar el CITE de Joyería (certificación, refacción, personal y uso del equipamiento)', 'El área de joyería del CITE está cerrada hace cerca de un año (junio 2025) y la infraestructura está deteriorada: techos cayendo, infiltración de agua, sin conexión a gas (funcionan con garrafas), equipos rotos/desconectados y una fuerte inversión municipal ociosa. Elaborar el diagnóstico de las causas del abandono y ejecutar el plan de reactivación: certificar el laboratorio con el Ministerio de Educación (primer instituto de joyería), refaccionar la infraestructura y definir personal y aprovechamiento del equipamiento para los emprendedores.', 69, 'EJE-04', 'Vigente', '🟢', 'Alta', '2026-11-30', 'Territorio', 'CITE de Joyería (Centro de Innovación Tecnológica, Costanera), La Paz', '-16.5252365,-68.1136201', NULL, 'Cita: «necesito un informe de por qué se cerró, razones, circunstancias... primero un diagnóstico»; «el plan: certificar el laboratorio con el Ministerio de Educación... aquí hay mucha plata invertida del gobierno municipal».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C243', 'Auditar el CITE de Joyería (producción real vs. facturación) y esclarecer su manejo', 'El CITE de Joyería opera con una sola persona y muchos equipos parados o subutilizados. El alcalde dispuso cerrar la producción, dejar el centro bajo la Guardia Municipal y que el equipo de sistemas verifique qué máquinas estuvieron encendidas y qué produjeron, para compararlo con lo facturado. Si la producción no cuadra con la facturación, remitir a auditoría.', 3, 'EJE-01', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'CITE de Joyería (Centro de Innovación Tecnológica, Costanera), La Paz', '-16.5252365,-68.1136201', NULL, 'Cita: «cerramos la producción... se queda en manos de la Guardia Municipal... que vengan los de sistemas y verifiquen qué máquinas han producido vs. qué se facturó... si ha producido más de lo facturado, algo no cuadra y lo mandamos a auditoría».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C242', 'Establecer el lavado y la fumigación periódica (2 veces al año) del Mercado Kollasuyo', 'Se ejecutó el lavado integral del mercado (lavado profundo con las caseras, desfregado de SIREMU y fumigación con amonio cuaternario contra bacterias, virus y hongos). Establecer este operativo de higiene al menos dos veces al año para precautelar la salud pública.', 67, 'EJE-04', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Mercado Kollasuyo, La Paz', '-16.4953151,-68.1166834', NULL, 'Cita: «el lavado integral... SIREMU hace el desfregado... al final el fumigado con amonio cuaternario para eliminar bacterias, virus y hongos... hay que hacer dos veces al año».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C241', 'Refaccionar el Mercado Kollasuyo (techo, cañerías y luminarias)', 'El Mercado Kollasuyo presenta filtraciones por el techo/calaminas y cielo falso, cañerías/desagües taponados (el último piso de carne se inunda porque no hay desfregado de cámaras) y luminarias y televisores de los pisos que ya no funcionan. Reparar el techo, destaponar y arreglar el sistema de desagüe (con Infraestructura) y reponer las luminarias y el equipamiento.', 67, 'EJE-04', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Mercado Kollasuyo, La Paz', '-16.4953151,-68.1166834', NULL, 'Cita: «tenemos problemas con los tubos, las cañerías... hubo un taponeo y no tuvimos apoyo para el desfregado de cámaras»; «entra agua de las calaminas»; «teníamos televisores en cada piso, ya no funcionan».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C240', 'Recuperar y regularizar el condominio de afectados de San Isidro (mal utilizado)', 'El condominio construido para damnificados de deslizamientos (San Isidro / Nieves-Linares) está siendo mal utilizado: los beneficiarios lo alquilan o dan en anticrético y volvieron a construir en sus lugares, dejando los departamentos sin uso y sin plan de contingencia. Recuperar y regularizar el condominio para reubicar a los afectados de esta y otras zonas.', 98, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'San Isidro (Nieves-Linares), La Paz', '-16.4800849,-68.1230973', NULL, 'Cita: «tenemos un condominio que fue hecho para afectados pero está siendo mal utilizado... lo han puesto en alquiler, anticréticos... tranquilamente tendríamos departamentos para afectados».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C239', 'Resolver el asentamiento estructural del Centro de Salud de Villa Armonía', 'El Centro de Salud de Villa Armonía tiene un asentamiento en el empalme entre la parte antigua y la nueva, por suelo de mala calidad y presencia de agua en profundidad; es parte de un problema global de estabilización de la zona. Evaluar y ejecutar la estabilización estructural del centro.', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Centro de Salud de Villa Armonía, La Paz', '-16.5084955,-68.1112923', NULL, 'Cita: «es de suelo de mala calidad y hay mucha agua, se puede asentar... es un problema global de estabilización, hay que verlo».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C238', 'Rehabilitar el frontón/complejo deportivo de San Antonio (baños, electricidad, canchas y parqueo)', 'El frontón/complejo deportivo de San Antonio está deteriorado: baños sin agua y sucios, techo con filtraciones, conexión eléctrica precaria (cables sueltos, focos que no funcionan), canchas sin mantenimiento (pintado/nivelado) y un parqueo inutilizado por una cuña/deslizamiento. Rehabilitar los baños, la instalación eléctrica y las canchas, y recuperar el parqueo con muro y relleno.', 54, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Frontón / complejo deportivo de San Antonio, La Paz', '-16.4896592,-68.1597073', NULL, 'Cita: «no puede estar así (la conexión eléctrica)... hay que darle mantenimiento... buenos baños, buena higiene... se puede rehabilitar el parqueo con muro y relleno».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C237', 'Verificar el derecho propietario y los permisos de construcción de las viviendas en riesgo del talud de Las Lomas', 'Tras el desprendimiento del talud de Las Lomas, se detectaron viviendas construidas al borde del talud, sobre el río y sobre cerros, aparentemente sin permisos, y con derivaciones de agua entre vecinos que agravan el riesgo. Verificar con urgencia el derecho propietario y los permisos de construcción de los terrenos afectados y ordenar las servidumbres de aguas.', 99, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Las Lomas (talud), La Paz', '-16.5275878,-68.0506086', NULL, 'Cita: «hay que ver el derecho propietario de todos estos terrenos y sus permisos de construcción... es urgente coordinarlo (Álvaro Viaña)»; «se han construido encima del río y encima de los cerros».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C236', 'Reutilizar los equipos médicos dados de baja e implementar el mantenimiento biomédico (convenio U. Católica)', 'En hospitales y centros de salud hay equipos costosos dados de baja o en desuso por fallas menores (camillas oxidadas, generadores de oxígeno sin uso, equipos botados). Integrar la información de activos, recuperar y reutilizar los equipos aún útiles, e implementar un centro de mantenimiento biomédico con convenio con la Universidad Católica (ingenieros biomédicos).', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Hospital Municipal (red de Cotahuma), La Paz', '-16.532702,-68.1404542', NULL, 'Cita: «lo que se da de baja se puede reutilizar en otros lugares... implementar un centro de mantenimiento biomédico... convenio con la Universidad Católica, ingenieros biomédicos». | [2026-05-26 · Villa Armonía] camilla botada recuperable en el centro; reforzar la recuperación de equipos.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C235', 'Inspeccionar e intervenir el deslizamiento de Las Lomas / línea amarilla (Buenos Aires)', 'En el sector de Las Lomas / Buenos Aires (cerca de la estación de la línea amarilla) una pasarela y parte del camino se deslizaron; la intervención anterior usó material del mismo terreno mal compactado que, con las fisuras y la lluvia, se infiltró y volvió a deslizar. Está controlado pero requiere una nueva inspección técnica e intervención definitiva.', 106, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Las Lomas / Buenos Aires (línea amarilla), Cotahuma, La Paz', '-16.5222299,-68.1388083', NULL, 'Cita: «esa pasarela ha deslizado... el material lo sacaron del mismo terreno... una fisura, el agua se entró y se ha inflado y ha deslizado... está controlado pero habría que ver otra inspección». | [2026-05-20 · evento] desprendimiento nocturno del talud: 2 domicilios afectados, 10 familias evacuadas; causa probable: agua de una cooperativa irregular (no Epsas); vuelo de dron + desmoronamiento manual controlado.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C234', 'Estudiar y rehabilitar el túnel/bocamina de drenaje de San Juan Cotahuma', 'Un túnel/bocamina de captación de agua (~50 años) que drena las aguas subterráneas de la ladera está taponeado por falta de mantenimiento, lo que provoca filtraciones y agrava los deslizamientos. Estudiar su estado y ejecutar el mantenimiento para reconducir el agua a su cauce natural.', 107, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-11-30', 'Territorio', 'San Juan Cotahuma (túnel/bocamina), La Paz', '-16.5112715,-68.1379215', NULL, 'Cita: «por aquí adentro pasa un túnel de agua, tiene unos 50 años... se ha taponeado... es un mantenimiento que hay que hacer... que se vaya a su cauce natural».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C233', 'Concluir la obra vial de Tacagua – San Juan Cotahuma y auditar el contrato', 'La avenida de conectividad al Alto (más de 10 zonas afectadas, >1 año desconectadas) quedó como obra inconclusa: solo se ejecutaron los 11 pozos de los pilotes (no los pilotes ni la plataforma volada), con un contrato fragmentado por servicios pequeños y Bs 1.400.000 comprometidos. Evaluar el estado real del avance, verificar la inscripción presupuestaria, auditar el proceso de contratación y darle continuidad hasta habilitar la vía (pilotes + plataforma volada + captación de aguas).', 106, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-10-31', 'Territorio', 'Avenida Tacagua – San Juan Cotahuma, La Paz', '-16.5091788,-68.1442524', NULL, 'Cita: «es una obra inconclusa que solamente nos han dejado los pozos de los pilotes... falta hacer los pilotes y la plataforma volada... vamos a hacer las auditorías correspondientes... verificar si está inscrito el presupuesto».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C232', 'Modernizar el centro de monitoreo del transporte (190 cámaras) con inteligencia artificial', 'El centro de monitoreo del SETRAM opera 190 cámaras (patios y rutas) de forma manual, lo que hace imposible vigilar todo (un operador solo cubre 2-3 cámaras). Incorporar inteligencia artificial y sensores para la detección automática, e integrar el monitoreo de todo el sistema de transporte a futuro (fibra óptica).', 113, 'EJE-03', 'Vigente', '🟢', 'Media', '2026-11-30', 'Territorio', 'Parque Urbano Central (patios SETRAM/Pumakatari), La Paz', '-16.5032519,-68.1256282', NULL, 'Cita: «aquí incorpora inteligencia artificial, porque es imposible que hayas podido mirar todo... el humano se cansa... hay que darle mejor utilidad»; «centro integrado de todo el transporte».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C231', 'Evaluar y reforzar la estructura metálica del Parque Urbano Central (desequilibrada)', 'La estructura metálica del Parque Urbano Central se desequilibró (se movió por el peso durante la inauguración, por un cálculo insuficiente) y quedó sin uso pese a su alto costo. Realizar la evaluación estructural y ejecutar el refuerzo/nivelación necesario para recuperarla y ponerla en uso con seguridad.', 48, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Parque Urbano Central (patios SETRAM/Pumakatari), La Paz', '-16.5032519,-68.1256282', NULL, 'Cita: «esta estructura que tanto ha costado no está siendo utilizada... se ha desequilibrado cuando hicieron la inauguración... hay que hacer la evaluación y ver cuánto se requiere».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C230', 'Impulsar el programa ''La Paz sin petardos'' y hacer cumplir la normativa', 'El uso de petardos y cachorros de dinamita afecta la convivencia y la seguridad (en manifestaciones, entradas folclóricas y fiestas), pese a existir normas municipales. Impulsar una campaña sostenida ''La Paz sin petardos'' y hacer cumplir/reforzar la normativa.', 66, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-12-31', 'Despacho', NULL, NULL, NULL, 'Cita: «me sumo plenamente a una campaña para que La Paz sea una La Paz sin petardos... hagamos dos, tres, cuatro años todos comprometidos en una ciudad sin petardos».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C229', 'Reparar la filtración de humedad y renovar el sistema eléctrico de la Biblioteca Municipal (hemeroteca)', 'En la hemeroteca (periódicos desde 1845, 82 títulos) hay humedad que ingresa desde el patio del vecino: cuando llueve el agua cae y penetra, amenazando la conservación del acervo. Además, el sistema eléctrico es deficiente desde hace años (informes reiterados sin atención) y es clave para la conservación. Cerrar/cubrir el ingreso de agua del patio y renovar el sistema eléctrico.', 88, 'EJE-06', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Biblioteca Municipal (Hemeroteca), La Paz', '-16.510849,-68.14352219999999', NULL, 'Cita: «esta es la humedad que viene del vecino... cuando llueve toda el agua cae aquí y penetra... lo que hay que hacer es cerrarlo»; «el sistema eléctrico es desde que yo llegué... pasamos el informe... nunca nos han tirado bola... que cambien el sistema eléctrico porque es de la conservación».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C228', 'Establecer la limpieza periódica (cada 6 meses) del Mercado Bolívar', 'El mercado no se limpiaba desde la pandemia (unos cinco años). Se ejecutó el operativo de limpieza integral (manguereada) y se establece su realización cada seis meses para garantizar la higiene.', 67, 'EJE-04', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Mercado Bolívar (calle Catacora, cerca de Plaza Murillo), La Paz', '-16.493565,-68.13167059999999', NULL, 'Cita: «esto se va a hacer cada seis meses para que tengamos higiene en cada uno de nuestros mercados».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C227', 'Transformar el Mercado Bolívar en un mercado digno (refacción integral)', 'El Mercado Bolívar (tradicional, a tres cuadras de la Plaza Murillo) está abandonado y deteriorado: puestos de adobe, piso de tierra, columnas descascaradas, techo/calaminas que filtran agua y baños muy pequeños e insalubres. Elaborar y ejecutar el proyecto de refacción/transformación en mercado digno, con baños adecuados y un espacio para los niños de las caseras, y revisar el alquiler que pagan (Bs 2.000/mes).', 67, 'EJE-04', 'Vigente', '🟢', 'Alta', '2026-12-31', 'Territorio', 'Mercado Bolívar (calle Catacora, cerca de Plaza Murillo), La Paz', '-16.493565,-68.13167059999999', NULL, 'Cita: «tengo un compromiso... este mercado tiene que transformarse, tiene que convertirse en un mercado digno»; «estamos a tres cuadras de la Plaza Murillo y está abandonado».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C226', 'Realizar la limpieza y el mantenimiento de la acera de la avenida Costanera (Las Cholas)', 'La acera de la costanera está abandonada y sin limpieza, dificultando el tránsito peatonal. Ejecutar la limpieza y el mantenimiento a través de la Subalcaldía Sur con apoyo de las empresas municipales.', 153, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Avenida Costanera (zona Las Cholas), La Paz', '-16.5447654,-68.09255809999999', NULL, 'Cita: «dando la instrucción para que a través de nuestra empresa (EMAVÍAS) y el equipo técnico de la subalcaldía sur hagamos la limpieza de esta acera».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C225', 'Actualizar el plan maestro de publicidad exterior de la ciudad (estudio de factibilidad por zonas)', 'La proliferación indiscriminada de letreros —especialmente en el Centro Histórico— genera contaminación visual. Actualizar el plan maestro / estudio de factibilidad que defina en qué zonas se permite publicidad exterior y en cuáles no.', 68, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Centro Histórico / Avenida Costanera, La Paz', '-16.5205996,-68.1178492', NULL, 'Cita: «se tiene que volver a hacer un estudio de factibilidad de dónde se pone publicidad y dónde no... el Centro Histórico... el ruido visual».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C224', 'Regularizar la publicidad en vía de la avenida Costanera y cuantificar el hurto de energía del alumbrado público', 'En la avenida Costanera (zona Las Cholas) se detectaron vallas publicitarias conectadas ilegalmente al alumbrado público (sin medidor propio), sin el mantenimiento que la norma exige cada dos años y a menos de 25 m del río (incumple la norma). Verificar con grúa/pluma cada letrero, cuantificar el consumo indebido de energía desde 2021, revisar los contratos y licencias con las empresas y denunciar los delitos comprobados (hurto/robo, peligro de estrago para los servicios públicos).', 68, 'EJE-01', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Avenida Costanera (zona Las Cholas), La Paz', '-16.5447654,-68.09255809999999', NULL, 'Cita: «los cables están colgados del alumbrado público... configuraría delito de hurto o robo... cuantificar cuánto habrían usado del erario municipal desde 2021».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C223', 'Ejecutar los estudios y la intervención integral de estabilización del muro cajón de Seguencoma (calle 16)', 'La obra de estabilización de la gestión anterior quedó insuficiente y con fallas: junta fría en los pilotes, pilotes descalzados sin apoyo (el hormigón fue disuelto por aguas ácidas), y el sistema de drenaje sin limpieza por cinco años que generó humedad y falló la cuña pasiva. Ejecutar tomografía de resistividad y monitoreo del movimiento, captar las vertientes que ingresan al cajón, verificar los pilotes de la línea posterior y ejecutar la intervención definitiva de estabilización, informando a la ciudad.', 106, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Muro cajón de Seguencoma (calle 16), La Paz', '-16.5384302,-68.0835557', NULL, 'Cita: «el trabajo que han hecho es insuficiente, posiblemente mal planificado... hay que hacer más intervenciones»; «comenzará con el agotamiento de los estudios... próxima semana haremos un informe de la situación».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C222', 'Renovar el extintor vencido y el equipamiento de seguridad del Centro de Salud de Tembladerani', 'El único extintor del centro venció el 16 de septiembre y el requerimiento de reposición (del 27 de marzo de 2026) sigue sin atenderse por burocracia. Reponer el extintor y completar el equipamiento de seguridad, reiterando el trámite hasta su entrega.', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Centro de Salud Tembladerani (Cotahuma), La Paz', '-16.5106032,-68.1425549', NULL, 'Cita: «el único extintor ha vencido el 16 de septiembre y la nota es del 27 de marzo»; «reiteraremos hasta que nos respondan».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C221', 'Regularizar el derecho propietario del inmueble del Centro de Salud de Tembladerani', 'Parte del inmueble (municipal según la justicia) está ocupada por terceros —una persona lo ocupa hace 14 años y dirigentes/organizaciones tienen llaves y ambientes—, lo que impide destinar esos espacios a la ampliación del centro. Sanear el derecho propietario y acordar con la junta de vecinos dos proyectos: la ampliación del centro de salud y el centro comunal vecinal.', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-10-31', 'Territorio', 'Centro de Salud Tembladerani (Cotahuma), La Paz', '-16.5106032,-68.1425549', NULL, 'Cita: «una señora vive aquí gratis hace 14 años... la justicia ha determinado que este escenario era municipal»; «generamos dos proyectos: uno, de una vez la salud aquí... y el segundo, su centro comunal».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C220', 'Garantizar que ningún paciente espere en la calle en el Centro de Salud de Tembladerani (guardia municipal)', 'Pese a la instrucción de no dejar pacientes en la calle, el centro no abría temprano (la gente hacía fila desde las 5:00 en la vía) alegando falta de portero. Asignar de inmediato un guardia municipal (o resolver la portería) para abrir y hacer pasar a los pacientes a un espacio digno mientras se elimina la fila con el sistema digital.', 51, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Centro de Salud Tembladerani (Cotahuma), La Paz', '-16.5106032,-68.1425549', NULL, 'Cita: «no podemos tener a los pacientes en la calle... le ponemos un guardia municipal y los haga pasar aquí a toditos y ustedes esperan aquí»; «nadie espera en la calle».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C219', 'Ampliar y reubicar el Centro de Salud de Tembladerani con accesibilidad y más horarios', 'El centro quedó muy pequeño frente a la alta demanda de la zona; funciona en ambientes acondicionados (un exlocal/curso prestado), con gradas que impiden el acceso de adultos mayores y personas en silla de ruedas, y sin baños. Buscar otro espacio o ampliar el actual con criterio de accesibilidad (rampas), dotar baños, aumentar horarios de atención y más médicos.', 51, 'EJE-02', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Centro de Salud Tembladerani (Cotahuma), La Paz', '-16.5106032,-68.1425549', NULL, 'Cita: «la infraestructura quedó muy pequeña, ha quedado muy reducida, hay mucha demanda... tenemos que buscar otro espacio, amplificar el lugar... quizás habría que aumentar horarios»; «adultos mayores tienen que subir un montón de gradas por otro lado».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C218', 'Ampliar y mejorar la infraestructura del Hospital Los Pinos', 'El hospital atiende a Zona Sur, Palca y Mallasa y quedó pequeño (la sala de internos es muy reducida) y con instalaciones a mejorar (cables sueltos/colgando). Ampliar el espacio, recomodar las instalaciones y gestionar equipamiento con donantes (rotarios, bomberos).', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Hospital Los Pinos, La Paz', '-16.5430,-68.0741', NULL, 'Cita: «se ha quedado bien pequeñito... ampliar este... no me gustan los cables sueltos, hay que recomodarlo... estoy buscando equipamiento, ya tengo posibles donantes, rotarios y bomberos».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C217', 'Reponer los extintores vencidos del Hospital Los Pinos y capacitar al personal en su uso', 'Los extintores del hospital están vencidos y sin recarga (sin presupuesto para reponerlos), y el personal no está capacitado para usarlos. Reponer los extintores y capacitar a todo el personal en su manejo (con los bomberos).', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Hospital Los Pinos, La Paz', '-16.5430,-68.0741', NULL, 'Cita: «está vencido... no tengo presupuesto para comprar, pero hay que conseguir, no puedes estar así en una cocina»; «la otra es la capacitación, no saben usarlos... todos tienen que saber».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C216', 'Devolver los cobros indebidos a los 87 pacientes y eliminar el cobro de certificados e informes médicos en el Hospital Los Pinos', 'Se identificaron 87 pacientes a los que se cobró indebidamente por certificados e informes médicos, que por ley son gratuitos. Devolver el dinero a esos pacientes (con carga notarial) y eliminar de forma permanente el cobro de certificados e informes médicos.', 51, 'EJE-02', 'Vigente', '🟢', 'Alta', '2026-08-15', 'Territorio', 'Hospital Los Pinos, La Paz', '-16.5430,-68.0741', NULL, 'Cita: «he encontrado 87 pacientes a los que se ha cobrado por certificados e informes médicos, que por ley son gratuitos... ya los hemos identificado, se les va a devolver su dinero... eso ha sido prohibido desde la semana pasada».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C215', 'Habilitar parte del Palacio Consistorial como museo por su centenario', 'El Palacio Consistorial cumple 100 años (inaugurado el 16 de julio de 1916). Recuperar parte de sus espacios y convertir una parte del palacio en museo, integrándolo a los festejos, trabajando con Ciudad Cultural.', 90, 'EJE-06', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Museos municipales (Calle Jaén / Casa de Murillo), La Paz', '-16.4954,-68.1356', NULL, 'Cita: «el palacio consistorial cumple 100 años... queremos recuperar parte de sus espacios y convertir parte del palacio consistorial en el museo, trabajando con el equipo de Ciudad Cultural».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C214', 'Implementar una tarjeta única de acceso a los museos municipales', 'Unificar el acceso a los museos municipales con una tarjeta única que permita recorrer todos con un solo boleto, mejorando la experiencia del visitante y los ingresos.', 90, 'EJE-06', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Museos municipales (Calle Jaén / Casa de Murillo), La Paz', '-16.4954,-68.1356', NULL, 'Cita: «hay que conectar una tarjeta de los museos, de uno a otro... vamos a trabajar en un proceso de que tengamos una tarjetita para ir por todos los museos».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C213', 'Ejecutar la conservación y restauración del patrimonio de los museos municipales', 'El patrimonio de los museos (piezas de oro y plata del Museo de Metales Preciosos, colección de platería de la Casa de Murillo, hemeroteca y documentos del s. XVI) sufre por humedad y filtraciones de agua (bóvedas, techos deteriorados tras el cambio de tejas, el conventillo contiguo sin alcantarillado). Ejecutar la conservación preventiva y restauración y resolver la humedad/filtraciones que dañan el patrimonio.', 90, 'EJE-06', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Museos municipales (Calle Jaén / Casa de Murillo), La Paz', '-16.4954,-68.1356', NULL, 'Cita: «el problema que tenemos acá es la humedad, nos ingresa agua... tenemos sales... los techos están deteriorados desde el cambio de tejas, falta una intervención... la casa contigua es un conventillo sin alcantarillado, como un pozo ciego».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C212', 'Incrementar el presupuesto de la Biblioteca Municipal para la compra de libros y la conservación', 'El presupuesto de la biblioteca es irrisorio (Bs 1.500 para compra de libros anuales, que no alcanza ni para un libro, y no se ha ejecutado) y viene reduciéndose. Incrementar el presupuesto para la compra de libros, revistas, derechos de autor y la conservación del material.', 84, 'EJE-06', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Biblioteca Municipal (Mercado), La Paz', '-16.4975,-68.1380', NULL, 'Cita: «1.500 bolivianos no sirve ni para un libro... no se ha gastado nada... se va reduciendo el presupuesto y no podemos actuar como debemos con la biblioteca».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C211', 'Digitalizar y conservar el acervo patrimonial de la Biblioteca Municipal', 'La Biblioteca Municipal (fundada en 1838, 25.130 ejemplares) tiene un acervo patrimonial (tomos religiosos, hemeroteca desde 1904) y una digitalización parcial (catálogo COA y hemeroteca). Completar la digitalización del acervo y la hemeroteca, y conservar/restaurar el material patrimonial.', 84, 'EJE-06', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Biblioteca Municipal (Mercado), La Paz', '-16.4975,-68.1380', NULL, 'Cita: «desde el 2021 hay sistemas que han estado intentando digitalizarse... el catálogo COA tiene 21.066 fichas de 25.330... la restauración de la hemeroteca desde 1904... 515 volúmenes empastados». | [2026-05-15 · Hemeroteca] periódicos desde 1845 (82 títulos); la humedad amenaza la conservación; digitalización hemerográfica en proceso.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C210', 'Recuperar las bibliotecas municipales cedidas y rehabilitar la de Achachicala', 'Se perdieron varias bibliotecas municipales zonales (Mariscal Santa Cruz, San Antonio, Periférica) porque se cedieron sus espacios a otros usos, y la de Achachicala está en ruinas. Recuperar esos espacios y rehabilitar la de Achachicala para no limitar el acceso a la lectura y la promoción del conocimiento.', 84, 'EJE-06', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Biblioteca Municipal (Mercado), La Paz', '-16.4975,-68.1380', NULL, 'Cita: «hemos perdido las bibliotecas de Mariscal Santa Cruz, San Antonio y Periférica porque se las ha dado a otros usos... la de Achachicala está en ruinas... el ir perdiendo espacios de bibliotecas zonales nos limita el acceso a la lectura».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C209', 'Esclarecer los recursos de reconstrucción y ejecutar la nueva construcción de nichos del Cementerio General', 'Hace tres años se destinaron ~Bs 3 MM ''para la destrucción'' (demolición) pero no hubo nueva construcción de nichos, con familiares esperando. Esclarecer qué pasó con esos recursos (revisar en detalle) y ejecutar la nueva construcción, con una reunión de especialistas y la Dirección de Riesgos.', 161, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Cementerio General, La Paz', '-16.4970216,-68.1518048', NULL, 'Cita: «tres millones para la destrucción... hace tres años seguimos insistiendo en la nueva construcción... algo ha pasado, tienes que revisar más detalles... reunión con el director de riesgos y especialistas».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C208', 'Digitalizar y modernizar el registro del Cementerio General', 'Modernizar el registro del cementerio: digitalizarlo e interoperarlo con el registro civil (evitar documentos duplicados en la descripción de la persona) y renovar los equipos para agilizar la atención.', 161, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Cementerio General, La Paz', '-16.4970216,-68.1518048', NULL, 'Cita: «existen documentos similares iguales que el SERECÍ al momento de registrar... lo vamos a implementar»; «hemos hecho que las mejores computadoras estén aquí para que la atención sea más veloz».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C207', 'Eliminar los sorteos de nichos del Cementerio General y permitir la elección directa y transparente', 'La asignación de nichos por sorteo puede ser manipulada. Eliminar el sorteo y permitir que las personas elijan directamente el nicho, haciendo el proceso lo más transparente posible.', 161, 'EJE-01', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Cementerio General, La Paz', '-16.4970216,-68.1518048', NULL, 'Cita: «los sorteos pueden ser manipulados... vamos a eliminar el tema de los sorteos para hacerlo lo más transparente posible... que las personas puedan elegir el nicho».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C206', 'Ejecutar el plan de intervención integral de la piscina de Orcojahuira (San Antonio)', 'La piscina/complejo deportivo de Orcojahuira está en abandono y deterioro peligroso: huecos en el piso donde juegan los niños, lámparas cayéndose, filtraciones de agua que afectan estructuralmente la piscina, duchas que no funcionan, casilleros usados como depósito y botiquín/farmacia vacíos. El alcalde instruyó a la Dirección de Deportes un plan de intervención integral para restaurarla.', 54, 'EJE-02', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Piscina de Orcojahuira (San Antonio), La Paz', '-16.5108,-68.1206', NULL, 'Cita: «hemos encontrado una piscina, un importante equipamiento urbano, en condiciones deplorables... huecos donde están la piscina, lámparas cayéndose, filtraciones que afectan estructuralmente... ya he solicitado a la Dirección de Deportes un plan de intervención integral».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C205', 'Habilitar los servicios externos de EMAVIAS y aprobar sus estatutos', 'Para generar ingresos, habilitar los servicios externos de EMAVIAS (producción de asfalto y su laboratorio de materiales, que puede descongestionar al laboratorio central que tiene a las subalcaldías en cola dos meses) y aprobar/revisar los estatutos de la empresa que definan sus atribuciones.', 16, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'EMAVIAS (planta de asfalto), La Paz', '-16.4501,-68.1470', NULL, 'Cita: «queremos estar en los servicios externos... el laboratorio central las tenía en cola dos meses, nosotros podemos descongestionarles»; «necesito el estatuto, que se revise la aprobación, qué están facultados y qué no».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C204', 'Coordinar con EPSAS la reposición del asfalto que rompe en las vías', 'EPSAS causa el 70-80% de los baches al romper las vías y reponer mal. Coordinar con EPSAS: que la reposición la haga EMAVIAS, exigir boletas de garantía anuales por el asfalto repuesto, aviso previo antes de romper y verificación de la reposición.', 112, 'EJE-08', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'EMAVIAS (planta de asfalto), La Paz', '-16.4501,-68.1470', NULL, 'Cita: «el 70-80% de los baches es por EPSAS... le hemos planteado que trabajen con EMAVIAS... solicitar boletas de garantía para que garanticen la reposición del asfalto... antes de romper nos tienen que avisar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C203', 'Investigar el robo de asfaltos y auditar las contrataciones de EMAVIAS', 'Se sustrajeron turriles de asfalto (con evidencia) sin que se abrieran procesos, y hay dudas sobre las contrataciones externas y los precios de compra. Investigar el robo de asfaltos a profundidad y auditar las contrataciones (precios, posibles contratos amañados) para deslindar responsabilidades.', 3, 'EJE-01', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'EMAVIAS (planta de asfalto), La Paz', '-16.4501,-68.1470', NULL, 'Cita: «se han robado asfaltos... con evidencia y todo, y no hay procesos abiertos, si esto queda en la impunidad van a seguir robándonos... vamos a seguir a profundidad, saber quiénes están detrás y qué tipo de contrataciones se hacen».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C202', 'Sanear y reflotar la situación financiera de EMAVIAS', 'EMAVIAS (empresa municipal de asfalto y bacheo) arrastra una deuda/pérdida acumulada de Bs 61 MM y pierde dinero cada año; necesita ~Bs 1,5 MM/mes de planilla con solo ~700.000 en caja. Reflotarla: hacer la valoración/ajuste contable, implementar contabilidad de costos y un plan de austeridad (cubrir los 17 cargos acéfalos ya ahorró Bs 1,5 MM/año), y el mantenimiento predictivo de la planta de asfalto, para que su costo de producción sea mejor que el privado.', 16, 'EJE-01', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'EMAVIAS (planta de asfalto), La Paz', '-16.4501,-68.1470', NULL, 'Cita: «la empresa EMAVIAS está en quiebra... tiene una deuda de 61 millones... necesitan 1,5 MM para la planilla y tienen 700.000 en caja... hemos instruido una valoración profunda... el reflotamiento significa hacerla mucho más eficiente».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C201', 'Investigar la sustracción del equipamiento del parque Laikacota', 'Los vecinos denuncian que la administradora de EMAVERDE del parque Laikacota se llevó o dejó desaparecer el equipamiento (bancas, sombrillas, basureros, asientos y los techos de resguardo) al cambiar de gestión, y que existe documentación fotográfica. Investigar la sustracción/pérdida del equipamiento y deslindar responsabilidades.', 3, 'EJE-09', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Parque Laikacota, La Paz', '-16.5089,-68.1267', NULL, 'Cita: «la señora que administraba se ha llevado sombrillas, bancas, se ha llevado de todo... hay documentación, fotografías... de la noche a la mañana ha desaparecido, ha cambiado la gestión y se lo ha sacado todo, asientos, basureros».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C200', 'Impulsar la reactivación económica de La Paz: feria ''Reactiva la Paz'' y mesa metropolitana público-privada', 'El alcalde declaró la reactivación económica como tercera emergencia (junto a riesgos y basura) por tiempo y materia. En el encuentro con la Cámara Departamental de Industrias, la gobernación, El Alto, Viacha y el viceministerio, el GAMLP se comprometió a sumarse a la alianza metropolitana público-privada: conformar la mesa técnica metropolitana y llevar adelante la feria ''Reactiva la Paz'' (ferias territoriales del productor al consumidor) para julio.', 142, 'EJE-04', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Reunión Reactiva la Paz (macrodistrito San Antonio), La Paz', '-16.5108,-68.1206', NULL, 'Cita: «hoy le hemos añadido la tercera, la reactivación económica como emergencia para trabajar por tiempo y materia»; «desde el Gobierno Municipal de La Paz estaremos al llamado del sector privado... para reactivar la economía»; la feria ''Reactiva la Paz'' se plantea para julio con mesa técnica metropolitana.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C199', 'Potenciar el desarrollo productivo y agrícola del área rural de Hampaturi', 'El área rural de Hampaturi tiene un enorme potencial (agua, energía, alimentos) para integrarse con el área urbana y reducir la dependencia de productos importados. Potenciar el desarrollo productivo: centro de mecanización agrícola, canal agrícola, capacitación agrícola y mercado de productores.', 156, 'EJE-04', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Subalcaldía / Maestranza de Hampaturi, La Paz', '-16.4337,-68.0307', NULL, 'Cita: «queremos que el área rural del municipio se integre al área urbana... tenemos un enorme potencial... el centro de mecanización agrícola, el canal agrícola, la capacitación agrícola, el mercado de productores».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C198', 'Ejecutar el ordenamiento y la reposición del mobiliario educativo en las unidades educativas', 'El mobiliario en las unidades educativas está distribuido de forma dispar y muy envejecido (en 9 años se cambió menos del 8%). Levantar un reporte con los directores sobre la demanda real por unidad, ordenar el mobiliario internamente y planificar su reposición (idealmente renovar todo en 5 años).', 62, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Subalcaldía / Maestranza de Hampaturi, La Paz', '-16.4337,-68.0307', NULL, 'Cita: «vamos a pedir un reporte a las unidades educativas y a los directores sobre este mobiliario... necesitamos un proyecto de ordenamiento del mobiliario educativo... ideal sería en 5 años cambiarles a todos».
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C197', 'Modernizar la Maestranza municipal y aumentar la producción de mobiliario educativo', 'La Maestranza produce el mobiliario escolar pero la demanda triplica su capacidad (unos 145.000 mobiliarios necesarios; produce ~700-840 juegos/año con 15 personas). Modernizar la maquinaria (adquirir la máquina semi-industrial cuya licitación falló), elaborar un plan de producción con factor de rendimiento e incrementar la producción un 20-30%.', 62, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Subalcaldía / Maestranza de Hampaturi, La Paz', '-16.4337,-68.0307', NULL, 'Cita: «la demanda es 3x lo que se produce... talvez es necesario modernizar la herramienta... incrementar entre 20 y 30% la producción... la licitación para la máquina semi-industrial no se pudo hacer».
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C196', 'Revisar el caso del Mercado Los Pinos y regularizar las patentes de los comerciantes', 'Los comerciantes del Mercado Los Pinos financiaron ellos mismos la construcción (Bs/US$ 28.500 por tienda) tras la estafa de la empresa constructora, que dejó la obra inconclusa y se fue del país. Llevan cuatro años esperando sus patentes/documentos del GAMLP. Revisar la historia completa del caso (contratos individuales y global, participación del GAMLP en la estafa) y regularizar las patentes de los comerciantes.', 67, 'EJE-04', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Mercado Los Pinos, La Paz', '-16.5430,-68.0741', NULL, 'Cita: «la empresa nos estafó... finalmente se fueron del país... hemos aportado cada tienda 28.500 dólares y por medio del mercado hemos acabado de construir... cuatro años esperando las patentes»; «quiero ver la historia completa, cómo han sido los contratos, qué participación tiene el gobierno municipal».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C195', 'Implementar el modelo de transformación de los residuos sólidos (biogás, combustible y valorización)', 'Avanzar hacia un modelo de manejo de residuos que industrialice, capte biogás, produzca combustible y derivados, y priorice la reutilización y valorización para que llegue menos residuo al relleno. (Sugerido: modelo de mediano plazo.)', 127, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Relleno sanitario de Alpacoma / Saka Churu, La Paz', '-16.5572,-68.1283', NULL, 'Cita: «tenemos un modelo de transformación del manejo de los residuos sólidos: queremos industrializar, sacar gas, generar reciclados, sacar combustible y derivados, que llegue menos residuo aquí y sea más reutilizado y valorizado».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C194', 'Ejecutar el mantenimiento, la estabilización y las obras urgentes del relleno de Alpacoma', 'El relleno presenta deslizamiento de macroceldas, grietas y planos de falla. Ejecutar el mantenimiento y la estabilización: pozos de captación profunda de lixiviado en las banquinas, sanja de coronación para las grietas, conformación y capa final según el manifiesto ambiental, control de taludes, y la obra urgente del muro cajón/bóveda antes de la temporada de lluvias.', 127, 'EJE-09', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Relleno sanitario de Alpacoma / Saka Churu, La Paz', '-16.5572,-68.1283', NULL, 'Cita: «hay que hacer pozos de captación profunda de lixiviados... la sanja de coronación... el cronograma del manifiesto ambiental, la capa final... es información urgente, hay que impulsar el muro cajón antes de la época de lluvias».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C193', 'Implementar el control de peso, calidad y humedad de los residuos en el relleno de Alpacoma', 'Instalar un control efectivo del ingreso de residuos: recalibrar la báscula con IBMETRO, sellar y verificar el sistema con reporte del pesaje en tiempo real a la oficina, desplegar brigadas (turnos) para el control de peso, calidad y humedad, y hacer una revisión paralela al SIREMU con acceso a las cámaras.', 127, 'EJE-09', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Relleno sanitario de Alpacoma / Saka Churu, La Paz', '-16.5572,-68.1283', NULL, 'Cita: «necesito que lo calibremos... el sistema sellado y verificado que me mande control en tiempo real a la oficina... hay que hacer brigadas para el control de peso... vamos a hacer una revisión paralela al SIREMU».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C192', 'Resolver la situación laboral de los trabajadores del relleno de Alpacoma', 'Unos 41-42 trabajadores especializados en residuos sólidos vienen operando el relleno 24/7 desde enero, sin contrato firmado (solo con una resolución del Ministerio de Trabajo), con el servicio de bus restringido y sin dotación de EPP/uniforme. Resolver su situación laboral (contratos, transporte y dotación de EPP); hay un acuerdo en curso con Gobernanza.', 127, 'EJE-09', 'Vigente', '🔴', 'Alta', '2026-06-20', 'Territorio', 'Relleno sanitario de Alpacoma / Saka Churu, La Paz', '-16.5572,-68.1283', NULL, 'Cita: «son parte de los 41 trabajadores que aún estamos tratando de resolver... venimos desde enero trabajando 24-7 con una resolución del Ministerio de Trabajo... nos han restringido el servicio de bus... los EPP no se dan desde enero».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C191', 'Extender el programa de alimentación a personas en situación de calle, adultos mayores y de bajos recursos', 'Ampliar los desayunos y almuerzos (al menos una comida diaria) a personas en situación de calle, adultos mayores y personas de bajos recursos que quedaron empobrecidas por la crisis, extendiendo también los albergues de invierno.', 74, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Terminal de Buses, La Paz', '-16.4887,-68.1418', NULL, 'Cita: «estamos viendo cómo extender estos desayunos y almuerzos incluso para los adultos mayores, para personas que no tienen recursos... al menos una comida diaria».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C190', 'Rehabilitar y abrir el albergue Zenobio López para personas en situación de calle', 'Ante la ola de frío (tres personas fallecieron en la Plaza San Pedro), se aceleró la rehabilitación del albergue Zenobio López para personas en situación de calle, que queda listo para habilitarse de inmediato.', 74, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-06-15', 'Territorio', 'Terminal de Buses, La Paz', '-16.4887,-68.1418', NULL, 'Cita: «se ha acelerado el proceso para rehabilitar el lugar de el Zenobio López, está prácticamente listo y a partir de hoy podemos habilitarlo... para que ustedes vayan allá».
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C189', 'Regularizar los bienes donados y completar la videovigilancia de la Terminal de Buses', 'Hay bienes donados a la Terminal con la transferencia inconclusa desde 2006 (no se pueden dar de alta/baja) y 7 puntos ciegos de cámaras. Regularizar la transferencia definitiva de los bienes y completar la videovigilancia con un centro de monitoreo (coordinado con la policía).', 112, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Terminal de Buses, La Paz', '-16.4887,-68.1418', NULL, 'Cita: «necesitamos la transferencia definitiva para poder dar el alta... el trámite ha quedado inconcluso»; «hemos detectado 7 puntos ciegos... estoy habilitando un centro de monitoreo que trabajamos junto con la policía».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C188', 'Modernizar la Terminal de Buses (señalética, imagen institucional y digitalización de tickets)', 'La Terminal (patrimonio cultural, no se puede modificar la infraestructura) requiere actualizar su señalética, indumentaria e imagen institucional y digitalizar el sistema de tickets/tacos (hoy en efectivo con colas).', 112, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Terminal de Buses, La Paz', '-16.4887,-68.1418', NULL, 'Cita: «estamos trabajando en la actualización de la señalética de la institución y la indumentaria... las botas institucionales... el sistema de tacos hoy se están desalzando las colas, va a desaparecer con una empresa».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C187', 'Reparar las aceras de Miraflores por acción comunal con los vecinos', 'Los vecinos de Miraflores ofrecen contribuir para la reparación de sus aceras si la subalcaldía colabora (acción comunal). Ejecutar la reparación de las aceras de manera conjunta con los vecinos.', 155, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Subalcaldía Centro, La Paz', '-16.4975,-68.1380', NULL, 'Cita: «tal vez nos pueda colaborar para completar... principalmente en Miraflores... les hemos dicho que ellos nos colaboren».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C186', 'Reutilizar las luminarias y bolardos obsoletos de la Subalcaldía Centro', 'La subalcaldía guarda luminarias (vapor de mercurio/metálicas) y bolardos obsoletos que quedarán en desuso con el cambio a LED de toda la ciudad. Evaluar su reutilización (conversión a LED con cintas/driver, o para proteger unidades educativas, plazas y jardineras). (Sugerido.)', 155, 'EJE-08', 'Vigente', '🟢', 'Baja', '2026-09-30', 'Territorio', 'Subalcaldía Centro, La Paz', '-16.4975,-68.1380', NULL, 'Cita: «tenemos planeado un proyecto de convertirlas a LED con cintas y driver... este material te sirve para proteger unidades educativas, repintarlo de amarillo... como adornos, plazas, jardineras».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C185', 'Renovar el equipamiento de trabajo y adecuar el almacén de la Subalcaldía Centro', 'Las máquinas y herramientas de los obreros de la Subalcaldía Centro son muy antiguas (equipos de 2003-2008) y no se compró material nuevo el año pasado; además el almacén actual (2-3 pisos) es inadecuado para almacenar y distribuir. Renovar el equipamiento y adecuar un almacén apropiado.', 155, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Subalcaldía Centro, La Paz', '-16.4975,-68.1380', NULL, 'Cita: «el material de trabajo no se ha renovado, están con el que compraron el 2024 y el año pasado no se compró nada... todas nuestras máquinas son antiguísimas»; «no es el mejor lugar para un almacén, hay que buscarle».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C184', 'Habilitar un albergue de invierno de emergencia para mujeres, niños y personas en situación de calle', 'Como medida de corto plazo, habilitar un albergue de invierno de emergencia para mujeres, niños y personas en situación de calle, aprovechando la capacidad instalada.', 74, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Albergue municipal de la calle Chuquisaca, La Paz', '-16.4913,-68.1415', NULL, 'Cita: «de emergencia, en el corto plazo, un albergue por invierno para mujeres y niños... para las personas en situación de calle».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C183', 'Corregir el sistema de atención de la línea de emergencia contra la violencia', 'Se reportó que las llamadas de la línea de emergencia no se atienden adecuadamente porque el sistema está obsoleto. Corregir el sistema para que las emergencias de mujeres, niños y víctimas de violencia se atiendan oportunamente.', 77, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Albergue municipal de la calle Chuquisaca, La Paz', '-16.4913,-68.1415', NULL, 'Cita: «estamos escuchando un reporte de que no se atiende adecuadamente las llamadas telefónicas... me dicen está obsoleto el sistema, pero en una llamada telefónica no debía estar obsoleto».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C182', 'Rehabilitar y poner en funcionamiento el albergue municipal de la calle Chuquisaca', 'El albergue municipal de la Chuquisaca, construido para proteger a mujeres víctimas de violencia y a sus hijos, está totalmente abandonado (sin ninguna persona acogida; la última estuvo hace ~3 meses). Ponerlo en funcionamiento con personal comprometido para darle un uso efectivo por tiempo y materia.', 74, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Albergue municipal de la calle Chuquisaca, La Paz', '-16.4913,-68.1415', NULL, 'Cita: «estamos en el albergue municipal de la calle Chuquisaca... construido para proteger a las mujeres que han sufrido violencia... está totalmente abandonado, no hay ni una sola persona... nos vamos con el compromiso de darle funcionalidad a este espacio».
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C181', 'Mejorar los servicios de atención del edificio del Mercado Camacho (adulto mayor, guardería y discapacidad)', 'El edificio del Mercado Camacho alberga servicios de atención (centro de adulto mayor, guardería, atención a personas con discapacidad y niños). El alcalde comprometió medidas para mejorar estos servicios.', 73, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Mercado Camacho, La Paz', '-16.5006,-68.1312', NULL, 'Descripción reconstruida a partir de una transcripción muy corrupta y de una inspección interrumpida; sin cita textual disponible.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C180', 'Reparar el muro colapsado que infiltra las fundaciones del edificio del Mercado Camacho', 'Un muro colapsado del edificio del Mercado Camacho está infiltrando agua en las fundaciones (drenaje deficiente), comprometiendo la estructura. Reparar el muro y resolver el drenaje.', 106, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Mercado Camacho, La Paz', '-16.5006,-68.1312', NULL, 'Descripción reconstruida a partir de una transcripción muy corrupta y de una inspección interrumpida; sin cita textual disponible.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C179', 'Regularizar y digitalizar el archivo y los activos del SETRAM', 'Hay ~300 activos sin asignar o perdidos y documentación de patios (2021-2023) sin digitalizar. Regularizar el inventario de activos (asignación y baja) y digitalizar el archivo del SETRAM bajo un sistema que permita ubicar cada documento.', 144, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'SETRAM (Parque Urbano Central), La Paz', '-16.5014,-68.1263', NULL, 'Cita: «son 300 activos que no aparecen... los activos han perdido, es grave»; «la digitalización no se ha hecho, tenemos que digitalizarnos... se va a proceder a digitalizar la documentación de patios». | [2026-06-08 · ampliada] sin digitalización; documentación de patios 2021-2023 sin archivar; el plan maestro de movilidad solo en digital; extintor del archivo vencido.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C178', 'Desarrollar los sistemas internos del SETRAM (flota, combustible y trámites)', 'Los sistemas del SETRAM son deficientes: la app de ubicación de buses tiene fallas, no hay control del consumo de combustible por bus (sospecha de fugas) y los trámites no están digitalizados; además faltan servidores propios. Conformar un equipo de desarrollo para mejorar el software de flota, el control de combustible y los trámites.', 144, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'SETRAM (Parque Urbano Central), La Paz', '-16.5014,-68.1263', NULL, 'Cita: «el software que identifica dónde están los buses tenemos que mejorar, existe pero no funciona bien... tiene que haber un promedio de consumo de combustible... seguro que aquí ha habido fuga de combustible... hay que desaparecer los billetes». | [2026-06-08 · ampliada] 14 sistemas; el software de ubicación de buses falla; faltan promedio y control de fuga de combustible; reunir las direcciones de SETRAM y Movilidad en un solo lugar (personal disperso en la Uruguay).');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C177', 'Ejecutar el mantenimiento integral de las paradas del Pumakatari', 'Las más de 640 paradas del Pumakatari no reciben mantenimiento desde hace ~5 años (abandono total, luminarias sin funcionar). Se está haciendo el relevamiento por ruta; ejecutar el mantenimiento priorizando las paradas de mayor recorrido antes del 16 de julio.', 144, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-07-16', 'Territorio', 'SETRAM (Parque Urbano Central), La Paz', '-16.5014,-68.1263', NULL, 'Cita: «cinco años sin mantenimiento, abandono total... son más de 640 paradas... vamos a dar prioridad a todo lo del Prado, desde la Montes, todas las paradas antes del 16 de julio». | [2026-06-08 · ampliada] 5 años sin mantenimiento de paradas; relevamiento por ruta en curso; prioridad Prado/Montes, todas mantenidas antes del 16-jul.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C176', 'Programar el lavado y la limpieza integral del Mercado Uruguay', 'Las caseras del Mercado Uruguay denuncian que el mercado no se lava desde la época del COVID (unos cinco años). Programar el lavado y la limpieza integral del mercado.', 67, 'EJE-04', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Subalcaldía Max Paredes, La Paz', '-16.4985,-68.1410', NULL, 'Cita: «desde la época del COVID que no lavaban el mercado... cinco años... ya le vamos a coordinar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C175', 'Ejecutar la intervención urgente del riesgo geotécnico en la avenida América (Max Paredes)', 'Un movimiento de tierra por una construcción dejó expuesto un talud, con el ángulo descompensado y drenaje deficiente, poniendo en riesgo la avenida América. El alcalde comprometió una intervención urgente por el cuidado de la vida.', 106, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Subalcaldía Max Paredes, La Paz', '-16.4985,-68.1410', NULL, 'Cita: «este lugar requiere de una intervención urgente y por supuesto que la vamos a hacer por el cuidado de la vida»; el drenaje de la vía es deficiente y el talud quedó expuesto por el movimiento de tierra.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C174', 'Entregar los textos escolares retenidos y regularizar el archivo de la Subalcaldía Max Paredes', 'Se encontraron textos escolares de gestiones anteriores nunca entregados (a repartir a los niños o a las bibliotecas) y documentación guardada fuera de lugar. Entregar los textos y regularizar el archivo (archivo y archivo histórico), auditando lo que se estaba guardando indebidamente.', 150, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Subalcaldía Max Paredes, La Paz', '-16.4985,-68.1410', NULL, 'Cita: «textos escolares que no han departido... hay que repartir igual, o a la biblioteca»; «la documentación no puede estar en cualquier lugar... el auditor demandamos para revisar eso que estaban guardando».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C173', 'Destrabar los trámites parados en la Subalcaldía Max Paredes', 'Se hallaron más de 1.500 hojas de ruta guardadas/paradas desde enero; algunos administrados llevan cinco meses esperando su trámite. Citar y destrabar los trámites represados para ponerlos al día.', 150, 'EJE-01', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Subalcaldía Max Paredes, La Paz', '-16.4985,-68.1410', NULL, 'Cita: «solo en el despacho, más de 1.500 hojas de ruta guardadas... han pasado del 9 de enero al 13 de junio, cinco meses esperando la gente».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C172', 'Dotar botiquín y equipamiento de seguridad a la Piscina de Obrajes', 'La Piscina Olímpica de Obrajes no cuenta con botiquín (pedido desde antes) ni con una salida de emergencia adecuada. Dotar el botiquín y el equipamiento de seguridad necesarios.', 54, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Subalcaldía Sur / Piscina de Obrajes, La Paz', '-16.5286,-68.1067', NULL, 'Descripción reconstruida a partir de una transcripción muy corrupta; sin cita textual disponible.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C171', 'Dar mantenimiento al edificio patrimonial de la Subalcaldía Sur', 'El edificio de la Subalcaldía Sur (patrimonial) requiere mantenimiento (puertas y otros elementos deteriorados). Ejecutar el mantenimiento preservando su carácter patrimonial.', 153, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Subalcaldía Sur / Piscina de Obrajes, La Paz', '-16.5286,-68.1067', NULL, 'Descripción reconstruida a partir de una transcripción muy corrupta; sin cita textual disponible.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C170', 'Renovar el equipamiento informático y las movilidades de la Subalcaldía Sur', 'El equipamiento informático (computadoras, impresoras) es antiguo y las movilidades están en mal estado. Renovar los equipos, migrar los datos a la nube y renovar/dotar las movilidades una vez pase la crisis.', 153, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Subalcaldía Sur / Piscina de Obrajes, La Paz', '-16.5286,-68.1067', NULL, 'Descripción reconstruida a partir de una transcripción muy corrupta; sin cita textual disponible.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C169', 'Resolver los 400 trámites parados en la Subalcaldía Sur', 'Se identificaron alrededor de 400 trámites administrativos parados por salir en la Subalcaldía Sur. Citar y destrabar esos trámites para ponerlos al día.', 153, 'EJE-01', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Subalcaldía Sur / Piscina de Obrajes, La Paz', '-16.5286,-68.1067', NULL, 'Descripción reconstruida a partir de una transcripción muy corrupta; sin cita textual disponible.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C168', 'Implementar el plan ''Mercados Dignos'' con ferias del productor al consumidor', 'Impulsar el plan ''Mercados Dignos para La Paz'' con ferias que conecten directamente a los verdaderos productores con el consumidor (evitando intermediarios que encarecen la cadena), coordinando con los productores por sector.', 67, 'EJE-04', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Mercado El Tejar, Max Paredes, La Paz', '-16.4953,-68.1521', NULL, 'Cita: «yo te sugiero así, ¿te parece? Ya, alcalde, es el plan de mercados dignos, mercados dignos para La Paz... vamos a hacer estas ferias con los verdaderos productores, del productor al consumidor».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C167', 'Ampliar el horario del Mercado El Tejar en temporada de frutas', 'En temporada de frutas la ''batida'' recoge a los productores/ambulantes muy temprano (8:00), impidiendo que las caseritas compren directamente del productor. Ampliar el horario del mercado en temporada de frutas para facilitar la venta del productor al consumidor.', 67, 'EJE-04', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Mercado El Tejar, Max Paredes, La Paz', '-16.4953,-68.1521', NULL, 'Cita: «estamos ampliando el horario a estas señoras; a las 8 de la mañana venía la batida y los recogía... en temporada de frutas se amplía un poquito y así vengan las caceritas a comprar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C166', 'Reubicar el contenedor de basura del Mercado Rodríguez que contamina los alimentos', 'Un contenedor de basura fue colocado sin planificación ni consulta junto a un puesto de verduras y frutas; cuando no se recoge a tiempo, la basura se extiende y contamina los alimentos, y genera un cuello de botella vehicular. Reubicarlo coordinando con los gremiales.', 127, 'EJE-09', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Mercado Rodríguez, La Paz', '-16.5001,-68.1389', NULL, 'Cita: «tenemos problemas con los contenedores de basura... se ponen bultos de cebolla, plátano, verduras y automáticamente se contamina el alimento... lo han puesto sin planificación, sin consultar a los vecinos ni a los gremiales».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C165', 'Coordinar con las empresas de la canasta básica el abastecimiento y la distribución a mayoristas', 'Para regular el abastecimiento de productos de la canasta básica (aceite, arroz, harina, azúcar), coordinar con las empresas productoras un listado de distribución a los mayoristas y un mecanismo de distribución municipal.', 66, 'EJE-04', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Mercado Rodríguez, La Paz', '-16.5001,-68.1389', NULL, 'Cita: «estamos buscando un ajo con las empresas que producen productos de la canasta básica —aceite, arroz, harina, azúcar— para tener un listado de cuántos distribuyen a sus mayoristas y cómo vamos a poder distribuir».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C164', 'Establecer inspecciones permanentes de control de precio, peso y calidad en los mercados', 'Ante la especulación durante el cerco, el alcalde estableció un cronograma de inspecciones permanentes (intendencia, guardia municipal y defensa al consumidor) en todos los mercados para exigir la exhibición del precio y controlar el peso, la calidad y el precio justo, sancionando los abusos.', 66, 'EJE-04', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Mercado Rodríguez, La Paz', '-16.5001,-68.1389', NULL, 'Cita: «ya hemos establecido un cronograma de inspecciones permanentes en todos los mercados de La Paz... se tiene que exhibir el precio, la caserita tiene que mostrar a cuánto está vendiendo».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C163', 'Estabilizar e intervenir la cancha Venus (césped sintético e iluminación) y apoyar las escuelas de fútbol', 'Es la única cancha grande de Pampajasí, con problema de estabilización del terreno. Una vez verificada la estabilización, cambiar a césped sintético e instalar iluminación, y apoyar con material a las escuelas de fútbol del sector (hoy sostenidas con aportes de los padres y alquiler de la cancha).', 54, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Cancha Venus, Pampajasí, La Paz', '-16.5402413,-68.2080703', NULL, 'Cita: «vamos a cambiar el césped sintético con las iluminarias... vamos a apoyar las escuelas de fútbol»; los padres pagan Bs 300/día de alquiler y compran el material.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C162', 'Reponer las afectaciones de la obra en Pampajasí (vía, cámaras, viviendas y cableado)', 'La obra dejó afectaciones sin reponer: la vía (debe perfilarse como estaba), las cámaras, viviendas con muros rajados y el cableado colgando (''parece colgador de ropa'', pendiente de tesar con DELAPAZ). Exigir a la empresa/riesgos la reposición comprometida.', 152, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Cancha Venus, Pampajasí, La Paz', '-16.5402413,-68.2080703', NULL, 'Cita: «la empresa y riesgos se han comprometido a reponernos, pero no sabemos cuándo ni cómo... hay que hacer la reposición, perfilar y dejar la vía como estaba, eso es un compromiso... tesar los cables con DELAPAZ».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C161', 'Evaluar la efectividad de la intervención geotécnica de Pampajasí antes de nuevas inversiones', 'Se invirtieron ~Bs 60 MM en pilotes y el embobedado del río Quisuara, pero las casas siguen ''estrangulándose'' (rajaduras, puertas que no cierran) y el embobedado se hizo sin estructura metálica (''hecho pomada''). El alcalde instruyó verificar si la intervención generó resultado antes de comprometer nuevas inversiones (incluida la cancha).', 106, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Cancha Venus, Pampajasí, La Paz', '-16.5402413,-68.2080703', NULL, 'Cita: «estamos hablando de casi 60 millones... ¿provocó o no provocó el resultado que ustedes esperaban?... quiero ver el efecto que tiene, se siguen estrangulando las casas después de toda esta intervención».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C160', 'Retomar el convenio con la ONG WCS para el bioparque Vesty Pakos', 'Existe una carta de intención con la ONG WCS (Wildlife Conservation Society) que quedó paralizada hace más de un año. Retomar y formalizar el convenio para apoyar la conservación en el bioparque. (Sugerido.)', 126, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Bioparque Municipal Vesty Pakos, Mallasa, La Paz', '-16.5737,-68.0810', NULL, 'Cita: «hay una ONG que se ha contactado, que es WCS... ya se había trabajado una carta de intención, sin embargo la habían paralizado hace más de un año».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C159', 'Crear rutas accesibles diferenciadas y áreas de descanso en el bioparque Vesty Pakos', 'El recorrido dura dos horas, que no toleran mamás con bebés ni personas con discapacidad. Crear rutas diferenciadas y accesibles (por tipo de animal y duración) y habilitar áreas de descanso/almuerzo para los visitantes.', 126, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Bioparque Municipal Vesty Pakos, Mallasa, La Paz', '-16.5737,-68.0810', NULL, 'Cita: «entran mamás con bebés, personas con discapacidad, y si el recorrido dura dos horas a veces no pueden... estamos en proceso de elaborar diferentes rutas».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C158', 'Mejorar el bienestar animal del bioparque Vesty Pakos (hábitat de pumas y jaulas de aves)', 'El hábitat de los pumas sufre contaminación auditiva por la carretera contigua (estrés) y las jaulas de aves permiten el ingreso de aves silvestres que contagian enfermedades y parásitos. Reubicar/aislar el hábitat de los pumas y corregir las jaulas de aves.', 126, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Bioparque Municipal Vesty Pakos, Mallasa, La Paz', '-16.5737,-68.0810', NULL, 'Cita: «como son pumas tienen la contaminación auditiva porque está al lado de la carretera, les genera estrés... aves silvestres ingresan a las jaulas y pueden contagiar enfermedades a las aves».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C157', 'Actualizar el plan de manejo e implementar la identificación de los animales del bioparque Vesty Pakos', 'El plan de manejo 2020-2030 tiene varios puntos incompletos y muchos animales no tienen el microchip prescrito ni historias clínicas. Actualizar el plan de manejo e implementar la identificación (microchip) y el registro clínico de todos los animales.', 126, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Bioparque Municipal Vesty Pakos, Mallasa, La Paz', '-16.5737,-68.0810', NULL, 'Cita: «hay varios puntos incompletos del plan... no tienen el microchip que está prescrito en su plan de manejo 2020-2030... eso también nos acumula al registro de las historias clínicas». | [2026-05-15] el comité científico pide esclarecer el caso ''biosibio'' (que no quede en impunidad) y consensuar la nueva administración del bioparque.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C156', 'Evaluar y reforzar el puente antiguo de Aranjuez', 'El puente antiguo (construido en los años 50) trabaja por encima de su capacidad de servicio (hoy pasan camiones de 300 quintales) con estribos deteriorados. Evaluar y reforzar el puente y darle un sistema de protección antes de la temporada de lluvias, ya que seguirá en uso mientras el nuevo no se conecte.', 112, 'EJE-08', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Puente de Aranjuez, La Paz', '-16.5595342,-68.0938792', NULL, 'Cita: «ese puente antiguo está trabajando por encima de su capacidad de servicio... necesitamos hacer una evaluación y probablemente un reforzamiento... un sistema de protección antes de la siguiente temporada».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C155', 'Resolver la accesibilidad y la conectividad del puente de Aranjuez', 'La obra estrangula la única vía de acceso de los vecinos (de 4,80 a 4,65 m) y el puente no tiene proyecto de conexión. Definir una ruta crítica con la empresa y la gobernación: habilitar una vía de acceso adecuada, resolver el terreno de la gobernación para la conexión y socializar el proyecto con los vecinos, con muros acústicos/de privacidad.', 112, 'EJE-08', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Puente de Aranjuez, La Paz', '-16.5595342,-68.0938792', NULL, 'Cita: «tenemos que buscarles soluciones... colocar tapas al canal para pasar de 4,80 a 4,65... no se ha previsto la conexión, va a quedar como un helipuerto colgado... vamos a hacer una ruta crítica con la empresa».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C154', 'Auditar el proyecto del puente de Aranjuez', 'El proyecto del puente (ruta Bicentenario) se ejecuta incompleto: no se conectaría a nada (''elefante blanco''), estrangula el acceso vecinal y se modificó varias veces sin socializar. El alcalde instruyó iniciar la auditoría de este proyecto (una de las 12 auditorías dispuestas).', 3, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Puente de Aranjuez, La Paz', '-16.5595342,-68.0938792', NULL, 'Cita: «ya hemos instruido y estamos iniciando una auditoría de este proyecto... son 12 auditorías que estamos empezando, una de ellas es esta, porque no se pueden hacer obras incompletas».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C153', 'Restaurar el ex relleno de Mallasa como santuario de avifauna y área verde recreativa', 'Se plantea restaurar el área para que se convierta en un santuario de avifauna y bosquecillo (con bosque de queñas, conectado al jardín botánico/bioparque por un corredor) y, junto con los operadores (taxistas/parrilleros), un espacio de recreación de fin de semana. (Sugerido: en fase de proyecto.)', 121, 'EJE-09', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Ex relleno sanitario de Mallasa, La Paz', '-16.5790,-68.0763', NULL, 'Cita: «la idea es que esta área se restaure para que se vuelva como santuario de avifauna... conectar con un corredor con el bioparque»; «un proyecto con los compañeros para que sea un lugar donde la gente quiera venir a disfrutar un fin de semana».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C152', 'Conformar y estabilizar los taludes y el lixiviado del ex relleno de Mallasa', 'Las macroceldas del ex relleno presentan asentamientos y deformación; el lixiviado (120-150 l/día) se acumula en turriles en mal estado. Hay riesgo de deslizamiento en época de lluvias. Conformar los taludes a la pendiente normada (3:1), tratar y elevar el lixiviado y hacer la evaluación geológica del sitio (junto con Alpacoma).', 127, 'EJE-09', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Ex relleno sanitario de Mallasa, La Paz', '-16.5790,-68.0763', NULL, 'Cita: «hay que hacer el peinado de taludes... una pendiente de 3 a 1... tenemos que hacer ahorita un asueldo del deslizado para evitar que en época de lluvia se deslice»; «una evaluación geológica del lugar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C151', 'Reinstalar las cámaras y recalibrar la báscula del ex relleno de Mallasa', 'La báscula de pesaje (capacidad 60 t) no se calibra desde diciembre y hace falta reinstalar el sistema de cámaras en la báscula y las celdas, urgente para la trazabilidad del material que ingresa (residuos de poda/orgánicos). Además, completar la digitalización de los registros (SIREMA).', 127, 'EJE-09', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Ex relleno sanitario de Mallasa, La Paz', '-16.5790,-68.0763', NULL, 'Cita: «el sistema de cámaras es urgentísimo para la trazabilidad... aquí es donde te ponen cualquier cosa»; «la última calibración fue en diciembre, hace cinco meses, hay que pedir que vuelva IBMETRO».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C150', 'Desburocratizar las denuncias e implementar la sanción directa en la Casa de la Mascota', 'Las denuncias por tenencia irresponsable o agresión pasan por 7-9 pasos (vía HRM/ventanilla), tardan semanas y se archivan. Implementar la sanción directa (impresora térmica de multas en sitio) y modificar la normativa de tenencia responsable para agilizar el procedimiento.', 80, 'EJE-05', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Casa de la Mascota (Villa San Antonio), La Paz', '-16.5108,-68.1206', NULL, 'Cita: «un proceso de denuncia tiene que pasar por 7, 8 o 9 pasos, tarda muchísimo... queremos llegar a la impresora térmica donde directamente se dan las multas... tenemos que modificar la normativa».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C149', 'Auditar la gestión de la Casa de la Mascota y regularizar sus activos', 'Se recibió sin inventario ni informes de transición (5 informes no entregados); hay 4 vehículos abandonados nunca dados de baja, microchips comprados/donados jamás implementados y activos sin baja. Completar el inventario, auditar el manejo, investigar el daño económico y deslindar responsabilidades.', 3, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Casa de la Mascota (Villa San Antonio), La Paz', '-16.5108,-68.1206', NULL, 'Cita: «no ha habido inventario... cuatro autos abandonados que nunca se han dado de baja... cajas de microchips que nunca se implementaron... hay que checar todas las responsabilidades e iniciar el proceso que corresponda».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C148', 'Refaccionar la infraestructura de la Casa de la Mascota', 'Los consultorios y quirófano no tienen condiciones sanitarias (paredes no lavables, sin esterilización), faltan chapas de puertas, el área de fluidoterapia está destrozada, el baño tiene fuga, hay goteras y no hay iluminación. Refaccionar con mejoras, sin nueva construcción (prohibida por el estudio de suelos por movimiento de tierra).', 80, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Casa de la Mascota (Villa San Antonio), La Paz', '-16.5108,-68.1206', NULL, 'Cita: «no son paredes lavables... no hay condiciones de un quirófano... el baño está fuera de servicio por una fuga... hay goteras... no hay luz... solo mejoras, sin infraestructura nueva por el estudio de suelos».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C147', 'Reponer los insumos, medicamentos y comida de la Casa de la Mascota y garantizar la cadena de frío', 'Se recibió con cero medicamentos, cero insumos de limpieza, sin gas y solo arrocillo de comida; el refrigerador de vacunas está roto, con la cadena de frío rota. Reponer medicamentos, insumos y alimento adecuado, y garantizar la cadena de frío de las vacunas antirrábicas, además del resguardo nocturno de los animales.', 80, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-06-06', 'Territorio', 'Casa de la Mascota (Villa San Antonio), La Paz', '-16.5108,-68.1206', NULL, 'Cita: «estamos en cero medicamentos, cero insumos de limpieza... de comida solo arrocillo... el día que llegamos tuvimos que comprar gas en taxi... se ha roto la cadena de frío, las vacunas antirrábicas quedan sin efecto».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C146', 'Dar de baja la maquinaria obsoleta de EMAVERDE', 'Buena parte de la maquinaria (heredada y desechada por la alcaldía) es irreactivable o cuesta más repararla que reponerla; ya se hizo el revalúo. Dar de baja la maquinaria obsoleta, publicándola y ofreciéndola antes a escuelas públicas (Ley 187).', 16, 'EJE-01', 'Vigente', '🟢', 'Baja', '2026-08-31', 'Territorio', 'EMAVERDE (planta central), Sopocachi, La Paz', '-16.5204,-68.1245', NULL, 'Cita: «al diciembre del año pasado se ha hecho un revalúo para maquinaria... antes de dar de baja tiene que publicarse y ofrecerse a otras escuelas públicas... ya tenemos todo para deshacernos».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C145', 'Regularizar el exceso de personal de EMAVERDE mediante jubilaciones', 'EMAVERDE tiene 461 funcionarios (394 obreros); alrededor de 160 ya deberían jubilarse y 67 jubilados siguen trabajando, lo que agrava el déficit. Regularizar el exceso de personal gestionando las jubilaciones que corresponden.', 16, 'EJE-01', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'EMAVERDE (planta central), Sopocachi, La Paz', '-16.5204,-68.1245', NULL, 'Cita: «de esos 400 operarios, ya por lo menos 160 deberían estar jubilándose, y hay 67 funcionarios ya jubilados pero que siguen trabajando».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C144', 'Reasignar a la Dirección de Deportes el control de sus activos deportivos', 'Los activos deportivos dependen del área de Salud (que no da abasto con hospitales y complejos). El alcalde instruyó que sea la Dirección de Deportes la que asuma el control de sus activos, con personal propio y registro de acceso/alquiler de canchas y gimnasios vía la aplicación.', 54, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Complejo Deportivo Luis Lastra, La Paz', '-16.516482,-68.1242801', NULL, 'Cita: «queremos que alguien solo de deporte tenga todo el control... el alquiler de canchas y gimnasios con registro... todo por la aplicación, directo al banco».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C143', 'Rehabilitar y reponer los servicios del complejo deportivo Luis Lastra', 'El complejo (piscina, gimnasio/CAR, cancha) debe recuperarse para el deporte y la juventud. Incluye reponer la piscina (reconexión de gas con YPFB + mantenimiento de calefones), abrir el gimnasio de alto rendimiento a todos con registro de acceso, resolver el riego de la cancha e inventariar y recuperar los equipos de sonido.', 54, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Complejo Deportivo Luis Lastra, La Paz', '-16.516482,-68.1242801', NULL, 'Cita: «vamos a hacer las gestiones con la gente de YPFB para que vuelvan a hacer la conexión de gas... mantenimiento de los calefones y volver a reponer esa piscina... el estadio Lastra va a ser el lugar del deporte».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C142', 'Auditar el manejo de la infraestructura deportiva Luis Lastra', 'Ante el abandono, el desmantelamiento de activos (calefones retirados desde diciembre), la falta de registros y la atención sin control, el alcalde dispuso iniciar la auditoría del manejo de esta infraestructura deportiva.', 3, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Complejo Deportivo Luis Lastra, La Paz', '-16.516482,-68.1242801', NULL, 'Cita: «empezaremos también a hacer la auditoría correspondiente en el manejo de la infraestructura deportiva».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C141', 'Cerrar e inventariar con notario el complejo deportivo Luis Lastra', 'El complejo se recibió sin inventario ni control de activos, con documentación botada y equipos desmantelados; el centro de psicomotricidad no atendía desde marzo. El alcalde ordenó cerrar las oficinas y la piscina e inventariar todo con notario.', 54, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-05-26', 'Territorio', 'Complejo Deportivo Luis Lastra, La Paz', '-16.516482,-68.1242801', NULL, 'Cita: «no hemos recibido con inventario estas dependencias... hemos dispuesto que se va a cerrar... iremos con notario a hacer una evaluación de toda la situación».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C140', 'Fortalecer la guardia municipal', 'La guardia municipal está muy debilitada (pocos efectivos para el control de parqueos y el orden en la zona). Fortalecerla con más personal y recursos.', 15, 'EJE-05', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Zona Gran Poder (Ch''ijini), Max Paredes, La Paz', '-16.4999,-68.1426', NULL, 'Cita: «guardia municipal igual está muy debilitada, pero estamos trabajando en eso... vamos a mejorar todo eso».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C139', 'Evaluar el cambio de ruta del Gran Poder por la Tumusla', 'Vecinos plantean que la entrada del Gran Poder vuelva a bajar por la Tumusla (recorrido tradicional) para mejorar la accesibilidad al hospital, que se congestiona con la aglomeración de fraternos. Evaluar el cambio de ruta para la próxima entrada. (Sugerido.)', 84, 'EJE-06', 'Vigente', '🟢', 'Baja', '2026-12-31', 'Territorio', 'Zona Gran Poder (Ch''ijini), Max Paredes, La Paz', '-16.4999,-68.1426', NULL, 'Cita: «tradicionalmente la entrada se bajaba por la Tumusla... por el hospital hay poca accesibilidad... quizás para la siguiente entrada poder analizarlo».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C138', 'Reparar las aceras de la ruta del Gran Poder por acción comunal con la asociación de carpinteros', 'La asociación de carpinteros (Vicente Choc, +70 años) ofrece poner el material para arreglar las aceras deterioradas de la ruta si la subalcaldía aporta la mano de obra (acción comunal). Ejecutar la acción comunal antes de la entrada.', 150, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-05-28', 'Territorio', 'Zona Gran Poder (Ch''ijini), Max Paredes, La Paz', '-16.4999,-68.1426', NULL, 'Cita: «estamos predispuestos a dar un monto económico para comprar el material y hacer una acción comunaria, de tal manera que la subalcaldía nos dé la mano de obra y se arreglen esas aceras».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C137', 'Revisar los garages de eventos con exceso de sonido en la Zona Rosa', 'Vecinos de la Zona Rosa (Belén) denuncian desde hace dos años dos garages/locales de eventos con exceso de sonido, con denuncias legales presentadas. Revisar su situación por la afectación a la convivencia y los derechos de los vecinos.', 141, 'EJE-07', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Zona Gran Poder (Ch''ijini), Max Paredes, La Paz', '-16.4999,-68.1426', NULL, 'Cita: «hay dos garages que desarrollan actividades sociales excesivas... los vecinos han hecho un sinfín de cartas hace dos años... es excesivo el tema del sonido».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C136', 'Instalar cámaras de seguridad y botones de pánico en la zona del Gran Poder', 'Con licencia y voluntad de los vecinos se ha programado la instalación de cámaras de seguridad y botones de pánico en la zona, que presenta alta inseguridad (hasta la subalcaldía fue quemada).', 81, 'EJE-05', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Zona Gran Poder (Ch''ijini), Max Paredes, La Paz', '-16.4999,-68.1426', NULL, 'Cita: «con la licencia y voluntad de los vecinos, la compra de cámaras de seguridad y botones de pánico porque es muy importante... se ha programado».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C135', 'Aumentar el personal de la Intendencia Municipal para el control del comercio', 'La zona comercial (del cementerio a la Plaza Eguino) concentra más de 100.000 actividades comerciales y solo 3 funcionarios de intendencia, sin capacidad de control. Aumentar el personal para controlar peso, calidad y precio.', 66, 'EJE-04', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Zona Gran Poder (Ch''ijini), Max Paredes, La Paz', '-16.4999,-68.1426', NULL, 'Cita: «para este lugar donde hay más de 100.000 actividades comerciales solo hay tres funcionarios para la intendencia municipal... no hay la capacidad para controlar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C134', 'Instalar bolardos metálicos en la acera del Santuario del Gran Poder', 'El Santuario del Gran Poder (patrimonio municipal) tiene la acera deteriorada por vehículos que se estacionan encima; los bolardos de plástico instalados el año pasado fueron volados. Instalar bolardos metálicos para proteger la acera del patrimonio.', 112, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-05-28', 'Territorio', 'Zona Gran Poder (Ch''ijini), Max Paredes, La Paz', '-16.4999,-68.1426', NULL, 'Cita: «este santuario ha sido declarado patrimonio... nos ha puesto unos volados de plástico y los han volado... pedimos la instalación de unos bolardos metálicos, no hemos tenido respuesta».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C133', 'Implementar escuelas de padres y profesionales en las unidades educativas', 'Los colegios derivan casos a la defensoría. Implementar escuelas de padres/talleres en los colegios y sumar trabajadores sociales/psicólogos en las unidades educativas fiscales. (Sugerido.)', 77, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «nos piden escuelas de padres... implementar trabajadores sociales y psicólogos en las familias/unidades educativas».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C132', 'Descentralizar el centro de terapia a las plataformas', 'Hoy hay un solo centro de terapia (en la Chuquisaca) y las víctimas deben trasladarse lejos. Descentralizar con terapeutas en cada plataforma para la restitución de derechos. (Sugerido.)', 77, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «el centro de terapia está en la Chuquisaca... descentralizar... que vuelva otra terapeuta a la plataforma».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C131', 'Implementar el programa ''mujer a mujer'' de acompañamiento a víctimas', 'Incorporar a mujeres que superaron situaciones de violencia como primer contacto y acompañamiento de las víctimas, para generar empatía y reducir la revictimización. (Sugerido.)', 79, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «incorporar en la red a alguna mujer que haya sufrido violencia... un programa de mujer a mujer».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C130', 'Brindar contención psicológica al personal de las defensorías', 'El personal carga trauma diario (''el basurero de la población''). El alcalde se comprometió a brindarles talleres/terapia de contención para cuidar al cliente interno.', 73, 'EJE-05', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «sería bueno que nos den a nosotros talleres, terapias porque cargamos tantas cosas... comprometido también los talleres».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C129', 'Fortalecer los albergues y crear la red de protección para víctimas', 'Falta capacidad de albergue (víctimas de violencia, niños sin familia). Crear una red de protección con hoteles/alojamientos privados, radio-taxis/móviles para operativos, y gestionar casas hogar para niños.', 74, 'EJE-05', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «coordinaciones con hoteles/alojamientos que sean parte de la red de protección... la red de radio-taxis... el fortalecimiento de los albergues».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C128', 'Digitalizar los casos de las defensorías', 'Los casos se llevan en carpetas físicas, sin cuadernos ni sistema; hay riesgo de pérdida de expedientes y de revictimización al reasignar personal. Digitalizar los casos (ciudad inteligente) con acceso objetivo al historial.', 77, 'EJE-05', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «la digitalización de los casos va a permitir que las personas, incluso si cambian, puedan acceder... y no tenga que volver a contar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C127', 'Gestionar un fiscal e investigador asignados a las plataformas SLIM', 'La brecha entre la defensoría y el Ministerio Público (esperas de 4-5 h, cobros, cambios constantes de personal) hace que las víctimas se cansen y desistan. Gestionar con el fiscal departamental un fiscal e investigador asignados a cada plataforma para acortar tiempos.', 73, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-06-15', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «sería un sueño que en cada defensoría haya un fiscal e investigador asignados... vamos a tener una reunión con el fiscal departamental».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C126', 'Trasladar la plataforma del Distrito 3 al inmueble recuperado de Nicolás Acosta', 'El edificio actual está en riesgo estructural (piso cediendo, vidrios rajados, estructura metálica debilitada sin refuerzo). La DASI recuperó un inmueble en la calle Nicolás Acosta; se lo adecuará de inmediato para trasladar la plataforma, previa valoración estructural del edificio actual.', 74, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «el piso está cediendo, es muy peligroso... tenemos un bien inmueble en la Nicolás Acosta recuperado... se va a adecuar lo más antes posible».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C125', 'Convertir los SLIM a atención 24/7 por equipos', 'Hoy atienden de 8:30 a 16:30; la violencia no tiene horario. Implementar atención 24/7 por equipos/postas (sin sobreexplotar al personal) y desconcentrar el servicio.', 77, 'EJE-05', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «me gustaría que los SLIM funcionen 24-7... la violencia no tiene horario... el 24-7 se da por equipos bien consolidados».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C124', 'Dotar movilidad y combustible a las defensorías', 'Las movilidades están arruinadas y sin gasolina; no pueden hacer rescates, verificativos, visitas domiciliarias ni traslados de menores (van con sus propios medios o radio-taxi). Dotar transporte y combustible.', 77, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-05-31', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «no hay movilidad... las movilidades están arruinadas, no tienen gasolina, no podemos hacer acciones».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C123', 'Aumentar el personal de las defensorías vía convenios con universidades', '6-7 profesionales atienden 15-20 casos/día. Se abrió el programa ''Juventud con Propósito'' con universidades (3 adheridas) para sumar profesionales (psicología, trabajo social, derecho, medicina) en territorio.', 77, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «estamos aperturando un programa que se llama juventud con propósito... tres universidades se han adherido».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C122', 'Separar los equipos de SLIM y DNA en las plataformas de atención', 'Por ley (348 y 548) el SLIM (violencia hacia la mujer) y la DNA (niñez) deben tener equipos especializados; hoy un solo equipo interdisciplinario atiende ambos por pares/impares, lo que anula la especialidad. Instrucción de conformar equipos separados.', 77, 'EJE-05', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Plataforma SLIM/DNA Distrito 3 (Nicolás Acosta), La Paz', '-16.5061,-68.1388', NULL, 'Cita: «por ley tanto la 348 como la 548 establecen tener una especialidad... una psicóloga no puede abordar una SLIM y después atender un niño».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C121', 'Gestionar el cambio de nombre del parque Hermann Maynard', 'Los vecinos de Achumani piden cambiar el nombre del parque Hermann Maynard (el homenajeado fue denunciado por pederastia el año pasado) por uno como ''parque de los niños''. Requiere una nota de los vecinos que entra por la comisión correspondiente del Concejo Municipal. (Sugerido.)', 153, 'EJE-07', 'Vigente', '🔴', 'Baja', '2026-07-31', 'Territorio', 'Achumani, La Paz', '-16.5309,-68.0719', NULL, 'Cita: «Hermann Maynard ha sido denunciado por pederastia el año pasado... queremos cambiar el nombre al parque por algo como el parque de los niños... generen la nota y la remiten al ejecutivo y al Concejo».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C120', 'Inspeccionar y corregir el riesgo eléctrico del Colegio Chumán', 'Una vecina denunció que las canaletas del Colegio Chumán tienen electricidad, con riesgo para los niños. La subalcaldesa de la zona Sur se comprometió a programar la inspección y corregir el riesgo eléctrico.', 153, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-05-28', 'Territorio', 'Achumani, La Paz', '-16.5309,-68.0719', NULL, 'Cita: «todas las canaletas tienen electricidad... tengo miedo de que los niños se electrocuten... vamos a incluirlo ya, coordinen la fecha».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C119', 'Controlar la velocidad de los camiones de áridos y extender el rompemuelles en Achumani', 'Los camiones de áridos bajan a alta velocidad, destruyen cunetas y muros y han provocado accidentes (una casa impactada, un minibús escolar chocado). El rompemuelles es esquivado. El alcalde instruyó extender el rompemuelles y controlar la velocidad para evitar accidentes.', 112, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-05-28', 'Territorio', 'Achumani, La Paz', '-16.5309,-68.0719', NULL, 'Cita: «unos camiones que bajan con áridos a alta velocidad... han acabado metiéndose en las casas y muros... lo que hemos solicitado es que se extienda el rompemuelle para que no lo esquiven».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C118', 'Remozar y mantener el parque de Achumani (áreas verdes y equipamiento)', 'Una de las áreas verdes más grandes de Achumani está descuidada: unos 15 árboles secos o cortados, sin pasto, sin basureros, sin asientos y la cancha sin arcos. El alcalde comprometió el remozamiento y mantenimiento adecuado, con la contribución de los vecinos.', 124, 'EJE-09', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'Achumani, La Paz', '-16.5309,-68.0719', NULL, 'Cita: «han muerto los árboles, el área verde ya no se ve verde, no hay pastos, han desaparecido los asientos, no hay basureros... a la cancha le han sacado los arcos»; los vecinos están dispuestos a contribuir.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C117', 'Retirar y reponer los bolardos viales dañados de la ciudad', 'Los bolardos de señalización vial dañados (rotos, torcidos, con pernos salidos que pinchan llantas) se retiran y luego se reponen y repintan con mantenimiento donde cumplen función de seguridad. Operación demandada hace tiempo por los vecinos de Achumani; se extenderá a toda la ciudad.', 112, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-05-21', 'Territorio', 'Achumani, La Paz', '-16.5309,-68.0719', NULL, 'Cita: «los bolardos que están en mal estado, rotos, torcidos, con los pernos salidos, los estamos retirando... luego volveremos a reponer con mantenimiento... iremos avanzando a toda la ciudad».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C116', 'Evaluar el convenio con la cementera (SOBOCE) por el material aluvial de la limpieza de cabeceras', 'El material aluvial que se retira en la limpieza de cabeceras podría interesar a la cementera (SOBOCE). Se plantea evaluar técnica y económicamente un convenio en que la empresa aporte maquinaria a cambio de un porcentaje del material, verificando qué cuencas producen material adecuado. (Sugerido: exploratorio.)', 106, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Bajo Llojeta, La Paz', '-16.5336,-68.1384', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C115', 'Impedir nuevos asentamientos y notificar las construcciones en la zona de riesgo de Bajo Llojeta', 'Hay casas expuestas a doble amenaza (inundación y caída de bloques/deslizamiento) construidas dentro de la faja del río y sin permiso. El alcalde instruyó impedir nuevos asentamientos, respetar la franja de seguridad del talud y notificar las construcciones, reforzando o reubicando las viviendas afectadas.', 106, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-05-27', 'Territorio', 'Bajo Llojeta, La Paz', '-16.5336,-68.1384', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C114', 'Ejecutar la intervención integral definitiva del talud y el río de Bajo Llojeta', 'Más allá de la reposición preventiva, se requiere una intervención integral: obras de contención verticales y horizontales, protección del talud (tablestacas o micropilotaje) y una sección hidráulica adecuada que conduzca el caudal. Se evaluará financiamiento con el banco de inversión.', 106, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Bajo Llojeta, La Paz', '-16.5336,-68.1384', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C113', 'Disponer maquinaria y personal para la limpieza preventiva del río de Bajo Llojeta cada temporada de lluvias', 'El río arrastra gran cantidad de material (mazamorra) y se tapona; la limpieza preventiva de cabeceras evitó eventos mayores. El alcalde instruyó programar maquinaria y personal cada temporada de lluvias para el control constante del sector.', 106, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-11-01', 'Territorio', 'Bajo Llojeta, La Paz', '-16.5336,-68.1384', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C112', 'Reponer la vía colapsada de Bajo Llojeta', 'El desborde/erosión del río en Bajo Llojeta colapsó ~200 m de vía (dos cuadras). El alcalde instruyó reponerla como intervención preventiva de corto plazo, manteniendo el sistema de limpieza mientras se define la solución definitiva.', 106, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-05-27', 'Territorio', 'Bajo Llojeta, La Paz', '-16.5336,-68.1384', NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C111', 'Implementar los hospitales móviles de salud preventiva para la mujer', 'Camiones con equipamiento especial (papanicolau y mamografía) rotando por los 23 distritos de La Paz para acercar el control preventivo a las mujeres, con horarios flexibles y servicios complementarios (p. ej. pediatría) que incentiven la asistencia y permitan detección temprana. Programa de ciudad.', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Hospital Municipal La Paz, La Paz', '-16.495964,-68.14580959999999', NULL, 'Cita: «los hospitales móviles para la salud preventiva de la mujer que son camiones con equipamiento especial rotando por todos los 23 distritos de la ciudad de La Paz para brindar servicios de papanicolau y mamografía».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C110', 'Auditar el uso del presupuesto de construcción del Hospital San Antonio', 'El Hospital San Antonio se recibió hace 5 años con presupuesto para terminarlo y no se concluyó ni quedó equipamiento. El alcalde anunció iniciar los procesos de auditoría para determinar qué ocurrió con esos recursos.', 3, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Hospital Municipal La Paz, La Paz', '-16.495964,-68.14580959999999', NULL, 'Cita: «no se ha podido terminar ni siquiera el hospital de San Antonio que tenía presupuesto, no sabemos qué ha ocurrido con el dinero y estamos iniciando los procesos de auditoría».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C109', 'Digitalizar las historias clínicas del Hospital La Paz', 'El hospital conserva más de un millón de historias clínicas en físico y aún usa máquinas de escribir. El alcalde instruyó digitalizarlas —accesibles en la nube y para el propio paciente— dotando además las computadoras necesarias.', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Hospital Municipal La Paz, La Paz', '-16.495964,-68.14580959999999', NULL, 'Cita: «más de un millón de historias médicas... queremos digitalizarlas, que estén en la nube y le pertenezcan al paciente»; «seguimos obligando a los internos a usar la máquina de escribir».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C108', 'Renovar el equipamiento obsoleto del Hospital La Paz', 'El equipamiento del hospital (70 años) es antiguo/obsoleto, especialmente en áreas críticas (quirófano, esterilización, laboratorio, diagnóstico). El alcalde comprometió gestionar la renovación del equipamiento.', 51, 'EJE-02', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Hospital Municipal La Paz, La Paz', '-16.495964,-68.14580959999999', NULL, 'Cita: «nuestros equipos son antiguos, obsoletos... especialmente en áreas críticas como quirófano, esterilización, laboratorio, diagnóstico»; POA solo alcanza a renovar ~20%.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C107', 'Reformular e incrementar el presupuesto del Hospital La Paz', 'El presupuesto del hospital solo alcanza hasta septiembre: del POA se aprobó Bs 8,2 MM de ~12 MM necesarios para funcionar el año, con solo Bs 50.000 para equipamiento. El alcalde instruyó reformular el presupuesto para que alcance hasta fin de año y mejorar el servicio.', 51, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Hospital Municipal La Paz, La Paz', '-16.495964,-68.14580959999999', NULL, 'Cita: «lo han presupuestado hasta septiembre... estamos ya trabajando en la reformulación del presupuesto»; director: «necesitamos 12 millones, nos aprobaron 8.200.000... 50.000 para equipamiento».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C106', 'Eliminar los cobros indebidos de prestaciones del SUS en el Hospital La Paz', 'Una vecina denunció cobros por prestaciones que en el SUS deben ser gratuitas (electrocardiograma 100 Bs, colocación de inyección). El alcalde instruyó eliminar esos cobros indebidos y garantizar la gratuidad de lo que corresponde al SUS.', 51, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-05-19', 'Territorio', 'Hospital Municipal La Paz, La Paz', '-16.495964,-68.14580959999999', NULL, 'Cita: «nos han cobrado por el electrocardiograma 100 bolivianos... por la colocada de inyección, y en el SUS no se paga»; el director explicó que cobran porque el presupuesto del SUS es insuficiente.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C105', 'Evaluar y reestructurar las rutas deficitarias del Pumakatari', 'Varias rutas (La Portada, Ciudadela, Mallasa) no son sostenibles. El alcalde pidió estudiarlas —con un tiempo de análisis— para reestructurarlas o darles alternativas sin desarticular el servicio al vecino, y ampliar frecuencias donde haga falta. (Sugerido: el alcalde pidió tiempo para el análisis.)', 144, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «hay un problema de las rutas que no son sostenibles... la portada, la ciudadela, Mallasa»; «démonos un tiempo para que después entramos a cambiar eso... hay que estudiar rutas y por cada ruta puede haber alguna alternativa».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C104', 'Implementar el sistema integrado de transporte de La Paz', 'El alcalde planteó avanzar en los próximos meses el sistema integrado de transporte en tres etapas —física (paradas y transferencias), operativa (horarios) y tarifaria (tarjeta única y, a futuro, tarifa plana)— conectando el Pumakatari con el teleférico y los operadores privados, más una app con GPS en tiempo real para el usuario. (Sugerido: es la visión de mediano plazo.)', 113, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «el sistema integrado de transporte en sus tres etapas: la integración física, la operativa y la tarifaria... con la misma tarjeta puedas pagar el teleférico, tu taxi y tu Pumakatari»; «queremos que la app esté conectada con GPS y en tiempo real».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C103', 'Mejorar el sistema de carga de combustible en los patios del Pumakatari', 'Los buses salen a cargar combustible a surtidores externos (Volcán y ESUD), lo que genera un recorrido muerto y demora; además no pueden salir con menos de medio tanque. El alcalde instruyó generar un sistema de carga de combustible en los propios patios y resolver el tema tributario (GRACO/ETM) para cargar combustible propio. (Complementa el compromiso financiero del 30-jun.)', 144, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «hay un recorrido muerto» a los surtidores; «estamos viendo cómo se puede generar un sistema de carga de combustible porque el bus tiene que salir del patio, ir al surtidor y volver»; «jalaremos el GRACO de ETM... la probabilidad sería cargar nuestros buses en nuestros propios patios».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C102', 'Habilitar comedor/descanso y estacionamiento de motos para el personal del patio Pumakatari', 'El personal del patio no tiene un espacio de comedor ni descanso y pidió ceder un container; también dejan sus motos sin un lugar delimitado. El alcalde derivó al secretario habilitar el comedor y delimitar el estacionamiento.', 144, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-05-22', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «no tenemos un comedor... queríamos pedirle que nos ceda uno de los containers para descansar»; «definan un lugar donde no afecte la operación, que entre con registro y salga con registro, delimitado y señalizado».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C101', 'Eliminar el cobro de pasaje a los trabajadores del Pumakatari y crear la tarjeta de funcionario', 'Se detectó que a los trabajadores del Pumakatari les cobran el pasaje cuando se desplazan. El alcalde instruyó dejar de cobrarles y crear una tarjeta de funcionario con pases limitados (como en el teleférico), controlando el uso.', 144, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-05-22', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «aquí les habían seguido cobrar a los trabajadores del Puma por desplazarse... podemos crear una tarjeta con pases limitados... se lo va controlando».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C100', 'Vacunar contra la influenza al personal del Pumakatari', 'El alcalde dio la orden de vacunar contra la influenza a todo el personal del servicio, empezando por quienes tienen más contacto con el público, la próxima semana.', 144, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-05-15', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «la próxima semana llevamos influenza para todos... empezaremos con los que tienen más contacto con la gente».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C099', 'Dotar uniformes nuevos al personal del Pumakatari', 'El personal (conductores, anfitriones, mantenimiento) no recibe uniforme nuevo desde hace tres años; en almacén solo quedan camisas antiguas. El fondo social para uniformes no fue asignado. El alcalde comprometió resolverlo.', 144, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-06-08', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «hace tres años que no les cambian uniforme»; «el tema de los uniformes, ese fondo social tampoco les habían asignado».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C098', 'Implementar un plan de mantenimiento predictivo documentado para la flota Pumakatari', 'El mantenimiento es manual y nocturno (revisión de aceite/fluidos), sin plan documentado ni mantenimiento predictivo; las novedades se anotan en el celular del técnico y no quedan en bitácora. El alcalde instruyó implementar un plan predictivo para llegar a ~100% de flota operable.', 144, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-06-30', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «tienes que tener tu plan de mantenimiento... llegar a un nivel de mantenimiento predictivo, ya no solo preventivo»; «cada situación debe quedar reflejada porque es historial, no en el celular».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C097', 'Reparar los ascensores de sillas de ruedas inoperables del Pumakatari y hacer su revisión diaria', 'Dos buses (VEA 38 y VEA 46) tienen el ascensor de sillas de ruedas inoperable, lo que impide el acceso a personas con discapacidad. La revisión se hace solo lunes, miércoles y viernes; el alcalde instruyó repararlos y revisarlos a diario.', 144, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-05-22', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «el VEA 38 no es operable su ascensor... si hay un bus que no tiene el ascensor no puede recepcionar a las personas con discapacidad... la inspección debía ser todos los días».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C096', 'Reponer los insumos de botiquín y bioseguridad de los buses Pumakatari', 'La inspección halló botiquines sin insumos (alcohol, povidona yodada, gasas, barbijos agotados) y bozales insuficientes para el préstamo a usuarios con mascotas. El alcalde instruyó reponerlos.', 144, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-05-15', 'Territorio', 'Patio Pumakatari de Chasquipampa, La Paz', '-16.5391515,-68.0476048', NULL, 'Cita: «alcohol ya no hay, barbijos ya no hay... por temas de descuento se acabaron varios insumos»; «si suben dos animalitos estamos en problemas porque no tenemos dos bozales».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C095', 'Evaluar el estado y el proceso de cierre técnico del ex botadero del Parque 3600', 'El sitio fue un botadero municipal que nunca tuvo un proceso formal de cierre técnico antes del deslizamiento de 2019. El alcalde pidió profundizar el análisis del estado del cierre. (Sugerido: no fue una instrucción firme; EMAVERDE es descentralizada y va solo como apoyo.)', 121, 'EJE-09', 'Vigente', '🔴', 'Media', '2026-06-30', 'Territorio', 'San Jorge–Kantutani (Puente Trillizos), La Paz', '-16.518604,-68.123241', NULL, 'Cita: «cuando hay un relleno sanitario se inicia el proceso de cierre... ¿se hizo?» — respuesta: «ninguno»; «lo vamos a profundizar este análisis».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C094', 'Regularizar el derecho propietario municipal del Parque 3600 e impulsar la expropiación para consolidarlo', 'El terreno del Parque 3600 tiene certificado catastral a favor del municipio pero sin respaldo legal (sin inscripción en Derechos Reales); el trámite está en el Concejo Municipal. Para consolidar el parque se plantea regularizar el derecho propietario municipal y evaluar la expropiación de las áreas con derecho propietario particular. (Sugerido: el alcalde lo trató como tema de más largo plazo.)', 99, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'San Jorge–Kantutani (Puente Trillizos), La Paz', '-16.518604,-68.123241', NULL, 'Cita: «solo teníamos visto técnico no legal... tiene que estar en Derechos Reales... está en el Consejo Municipal para que salga la inscripción»; «hacer la expropiación para que se consolide el parque... todavía verificaremos».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C093', 'Concluir y asfaltar la vía que conecta la zona con la avenida Cantutani', 'El alcalde señaló la necesidad de concluir y asfaltar la vía que debe conectar la zona del Parque 3600 con la avenida Cantutani, por su importancia para la conectividad del sector.', 112, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'San Jorge–Kantutani (Puente Trillizos), La Paz', '-16.518604,-68.123241', NULL, 'Cita: «hay una vía más abajo que después tiene que conectar esta zona con la avenida Cantutani... tenemos que provocar su conclusión, su asfaltado, porque es una vía importantísima».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C092', 'Instalar las mesas técnicas de diálogo con los vecinos damnificados y definir la ruta crítica del Parque 3600', 'Tras 7 años sin respuesta a los damnificados del deslizamiento de 2019, el alcalde comprometió instalar mesas técnicas de diálogo con los vecinos de los dos sectores (San Jorge Cantutani y 14 de Septiembre) y ambas subalcaldías (Cotahuma y Sur) para revisar la documentación de derecho propietario y definir una ruta crítica de solución.', 93, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-05-14', 'Territorio', 'San Jorge–Kantutani (Puente Trillizos), La Paz', '-16.518604,-68.123241', NULL, 'Cita: «vamos a generar las mesas de diálogo... a través de nuestro subalcalde de Cotahuma... vamos a convocar a la subalcaldesa de Sur... establecemos una ruta crítica»; los vecinos piden audiencia y traerán su documentación.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C091', 'Paralizar y hacer cumplir la paralización de las construcciones no autorizadas en el Parque 3600 y el Teatrín', 'En la inspección al Parque 3600 y el Teatrín (ex botadero con deslizamiento activo, área protegida y franja de seguridad) se detectaron construcciones sin autorización municipal. El alcalde instruyó paralizarlas, notificarlas y resguardar permanentemente el terreno, por tratarse de una zona no edificable donde está en riesgo la vida.', 149, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-05-08', 'Territorio', 'San Jorge–Kantutani (Puente Trillizos), La Paz', '-16.518604,-68.123241', NULL, 'Cita: «no hay ninguna autorización... se notifica la paralización de las construcciones»; «hemos dado la instrucción al subalcalde para que esté permanentemente resguardando este terreno»; «vamos a desplegar personal para que esté verificando que se dé cumplimiento a este compromiso».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C090', 'Recuperar la información no entregada por la gestión saliente en salud', 'La gestión saliente entregó solo el 33% de la información requerida por ley (falta el 67%) y no respondió 151 notas. El alcalde instruyó exigir la información faltante y las respuestas pendientes.', 3, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-05-20', 'Territorio', 'Hospital Municipal La Portada, La Paz', '-16.4892073,-68.1657426', NULL, 'Cita: «de toda la información que nos tenían que haber entregado por ley nos han entregado 33%, falta 67%... de 151 notas no nos han dado respuesta a ninguna».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C089', 'Instituir inspecciones sorpresa periódicas a los hospitales y centros de salud municipales', 'El alcalde estableció como práctica permanente de la gestión realizar inspecciones sorpresa, en distintos horarios y sin previo aviso, a todos los hospitales y centros de salud de primer y segundo nivel, para verificar y elevar el estándar de calidad del servicio. (Compromiso de ciudad: futuras menciones lo enriquecen, no lo duplican.)', 50, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-06-06', 'Territorio', 'Hospital Municipal La Portada, La Paz', '-16.4892073,-68.1657426', NULL, 'Cita: «vamos a hacer estas inspecciones permanentemente, de sorpresa... en diferentes horarios... en todos los hospitales y centros de salud de primer y segundo nivel». | [2026-07-23 · Tembladerani] «vamos a hacer estas inspecciones a los 67 centros de salud prácticamente todos los días... control temprano»; informe inmediato al Ministerio/SEDES y reporte de médicos ausentes.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C088', 'Digitalizar los expedientes clínicos del Hospital La Portada', 'El hospital conserva 93.000 historias clínicas en físico y se halló documentación clínica original desechada en un depósito. El alcalde instruyó digitalizar los expedientes trabajando con el equipo de tecnologías, para liberar espacio y proteger la información de los pacientes.', 51, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-07-06', 'Territorio', 'Hospital Municipal La Portada, La Paz', '-16.4892073,-68.1657426', NULL, 'Cita: «actualmente tenemos 93.000 historias clínicas»; «todo esto tenemos que digitalizar... vamos a trabajar con nuestro equipo de tecnologías»; documentación original de pacientes hallada botada en un depósito.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C087', 'Equipar las ambulancias municipales y eliminar el cobro del servicio', 'Las ambulancias del servicio municipal circulan sin oxígeno ni equipamiento mínimo y, según se denunció, se condiciona el traslado al pago previo. El alcalde instruyó equiparlas y eliminar el cobro.', 51, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-05-20', 'Territorio', 'Hospital Municipal La Portada, La Paz', '-16.4892073,-68.1657426', NULL, 'Cita: ambulancias «no tiene oxígeno, no tiene ningún tema, solo han sacado los asientos y puesto una camilla»; «el sistema de ambulancia es del municipio, tú llamas y te preguntan si tienes para pagar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C086', 'Recuperar el acelerador lineal donado (USD 3 MM) que nunca llegó al Hospital La Portada', 'Un convenio de 2019 con la organización Radiating Hope donó un acelerador lineal valorado en ~USD 3 millones que debía llegar en 2021 y nunca llegó al hospital. El alcalde ordenó evaluar qué pasó, gestionar su llegada y, de ameritarlo, auditar el proceso.', 3, 'EJE-02', 'Vigente', '🔴', 'Crítica', '2026-06-06', 'Territorio', 'Hospital Municipal La Portada, La Paz', '-16.4892073,-68.1657426', NULL, 'Cita: «una donación el año 2019, un acelerador lineal de 3 millones de dólares... tenía que llegar el 2021 y no está en este hospital... si esto amerita una auditoría lo vamos a tener que realizar».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C085', 'Poner en pleno uso y al día el mantenimiento del tomógrafo del Hospital La Portada', 'El tomógrafo (16 cortes) está subutilizado —unos 10 estudios desde el 1 de mayo frente a una capacidad de ~40/día— y no recibe mantenimiento preventivo desde 2024. El alcalde instruyó ponerlo al día y aprovechar su capacidad, incluso para atender a otros hospitales de la red.', 51, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-06-06', 'Territorio', 'Hospital Municipal La Portada, La Paz', '-16.4892073,-68.1657426', NULL, 'Cita: «ese tomógrafo no ha tenido el mantenimiento preventivo desde el año 2024» y «ha hecho 10 atenciones desde el 1 de mayo cuando se pueden hacer 40 por día... podríamos prestar servicios a otros hospitales».');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C084', 'Corregir las deficiencias operativas del Hospital La Portada', 'El alcalde constató en la inspección sorpresa (5:30 am) múltiples deficiencias operativas en un hospital que debe funcionar 24/7 y ordenó corregirlas: recibir a los pacientes dentro del hospital, sanear medicamentos vencidos, reponer extintores, cambiar sábanas a diario, resolver la iluminación, garantizar personal médico permanente y recuperar el equipamiento (camillas) desechado.', 51, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-05-13', 'Territorio', 'Hospital Municipal La Portada, La Paz', '-16.4892073,-68.1657426', NULL, 'Cita: hospital «24-7» con pacientes esperando en la calle y las puertas cerradas; medicamentos vencidos y epinefrina vencida (10-may) en el carro de emergencia; «los extintores ya están vencidos»; sábanas que «tienen que cambiar todos los días»; «no sabían dónde prender la luz»; camillas desechadas y una sin freno; los consultorios abren a las 8:00 en un hospital que debería atender 24/7.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Atender la problemática de seguridad ciudadana nocturna (night clubs y zona roja) en el sector del Puente de las Américas', 'Vecinos denunciaron que continúan funcionando night clubs y construcciones irregulares cerca de universidades y colegios en el sector del Puente de las Américas, generando lo que califican como una ''zona roja'' con inseguridad para las familias. El alcalde se comprometió a impulsar intervenciones y una mesa de trabajo conjunta con los vecinos y el equipo técnico de la subalcaldía para buscar una solución.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Fiscalizar la ejecución del POA 2025 entregado por la dirigencia vecinal', 'La dirigente vecinal entregó al alcalde toda la documentación del POA (incluyendo el POA 2025) señalando que obras comprometidas —como el arreglo del atrio/plaza del poeta y la llegada de la cinemateca— no se ejecutaron pese a estar presupuestadas, y que solo firmaron los controles sociales sin respuesta a sus solicitudes. El alcalde recibió la documentación y se comprometió a coordinar su revisión a través de la subalcaldía.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Programar inspección técnica al muro de contención de Seguencoma', 'Como parte del plan de inspecciones tempranas que se está iniciando, el alcalde propuso agendar una siguiente visita técnica al sector de Seguencoma, donde se han detectado nuevas filtraciones y asentamientos diferenciales en el pavimento, para revisar el trabajo realizado en los cajones de contención y la cuña pasiva.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Evaluar y declarar la alerta roja municipal ante el fenómeno de El Niño', 'Con la probabilidad del fenómeno de El Niño en 60% (y proyectada a 90% en septiembre), se planteó declarar una alerta roja en la ciudad para disponer de más recursos económicos y de tiempo frente a zonas de riesgo (deslizamientos, ríos subterráneos). El alcalde señaló que la declaratoria debe definirse con cuidado para no perjudicar el desarrollo inmobiliario y quedó pendiente de trabajarse en la mesa técnica.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Conformar la mesa técnica y definir el plan de intervención integral de la Avenida del Poeta', 'Tras la inspección se identificaron dos focos de riesgo en la avenida: la diferencia de materiales en la superficie (cemento rígido, asfalto y adoquín) que provoca pérdida de control vehicular en época de lluvia, y problemas de mantenimiento e hidrogeología en el embovedado antiguo y nuevo del río Chocayapu, que no funcionan como bóvedas gemelas y presentan sifonamientos. El alcalde instruyó generar una orden de despacho para constituir una mesa técnica con la Secretaría de Ciudad Conectada, la Secretaría de Ciudad Planificada y Habitable, la empresa municipal Mavías y la Subalcaldía, para definir un cronograma de trabajo de corto, mediano y largo plazo que resuelva ambos problemas.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Completar la entrega de equipamiento de protección personal a los trabajadores', 'Entrega simbólica de ropa de trabajo, cascos y overoles en el arranque; completarla para todo el personal.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Brindar apoyo social a la persona adulta mayor reubicada de la calle Nieves–Linares', 'Adulto mayor a cargo de una persona con discapacidad, reubicado por la demolición; continuar el acompañamiento social.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Ejecutar la demolición controlada y restitución de la vía en la calle Nieves–Linares', 'Edificios en riesgo de colapso tras años de abandono; demolición controlada (~3 meses), valoración del terreno y restitución de la vía.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Ejecutar el programa integral de mejoramiento definitivo de vías fundamentales', 'Más allá del bacheo temporal, restitución y mejoramiento definitivo de las vías fundamentales de la ciudad (arranca en un par de meses).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Mejorar la iluminación de la ruta del Gran Poder para la festividad', 'Mejorar el alumbrado de la ruta del Gran Poder para la festividad (unas 130 mil personas circulando de noche).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Ejecutar el plan de bacheo intensivo en toda la ciudad', 'Programa de bacheo (~Bs 10 millones) con asfalto en frío en todos los macrodistritos; arranca simbólicamente en la ruta del Gran Poder.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Pagar los sueldos atrasados a los trabajadores de EMAVERDE', 'Hasta tres meses de sueldos sin pagar por el déficit; resolver el pago de forma urgente (separado del saneamiento estructural).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Sanear la situación financiera integral de EMAVERDE', 'Déficit estructural de EMAVERDE arrastrado de la gestión anterior (contrataciones fuera de norma). Saneamiento estructural de la empresa.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Recoger y reciclar los troncos podados y caídos del Jardín Botánico', 'Troncos de poda y caídos acumulados; recogerlos con el equipo de poda (el lunes) y procesarlos para reciclaje.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Realizar la evaluación de desempeño del personal del Jardín Botánico', 'Evaluación del desempeño de cada trabajador del parque (distinta del inventario de especies, que va en el parque-escuela).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Reforzar la seguridad perimetral del Jardín Botánico', 'El sistema de seguridad del parque es deficiente; reforzar todo el perímetro.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Rediseñar las estructuras del Jardín Botánico con criterio arquitectónico', 'El depósito y la cocina no condicen con el parque; rediseñarlas con criterio arquitectónico acorde al jardín.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Habilitar el Jardín Botánico como parque-escuela', 'Tras años de descuido, convertirlo en un parque acogedor y educativo: habilitar los invernaderos y espacios para estudiantes y familias.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Remitir a auditoría la falta de pago del servicio de agua de la gestión anterior', 'La deuda con EPSAS se acumuló porque la gestión anterior no pagó desde 2024. El alcalde dispuso remitir el caso a auditoría.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Restituir el agua del Jardín Botánico y los parques (deuda con EPSAS)', 'Deuda de Bs 3,3 millones con EPSAS impaga desde 2024 cortó el agua a los parques (hoy con cisternas). El alcalde cerró un plan de pagos y EPSAS reconecta el lunes.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Registrar el proyecto de gradas eléctricas para San Antonio', 'Se instruye iniciar un nuevo proyecto para instalar gradas eléctricas (escaleras mecánicas) en San Antonio. El alcalde indicó que la responsabilidad ya fue asignada a ''César'' desde junio, aunque no se especifica su cargo ni unidad exacta, por lo que corresponde confirmar el área municipal a cargo antes de avanzar.', 113, 'EJE-08', 'Vigente', '⚪', 'Media', NULL, 'Despacho', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Revisar la normativa de colores hospitalarios y revertir los colores políticos aplicados en el Hospital San Antonio', 'Se identificó que el hospital recibió colores asociados a un partido político en lugar de seguir la normativa de establecimientos de salud. El alcalde pidió corregirlo, remarcando que es un tema de salud y no político.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Gestionar el proceso de contratación y presupuesto para el equipamiento del Hospital San Antonio', 'Pese a que la obra civil avanza, no existe contrato, presupuesto ni especificaciones para equipar el hospital una vez concluido; incluso ambientes ya cerrados (como la sala de tomografía) tendrían que romperse de nuevo para instalar equipos. El alcalde instruyó iniciar la gestión del equipamiento en paralelo a la obra.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Decidir sobre la inclusión del generador de oxígeno (Bs 2.000.000) en el equipamiento del Hospital San Antonio', 'Uno de los cambios propuestos es retirar el generador de oxígeno del equipamiento del hospital, cuyo costo ronda los Bs 2.000.000 más mantenimiento. El alcalde señaló que no se puede sacar del alcance sin un informe técnico que respalde la decisión.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Revisar y corregir el diseño de flujos hospitalarios del Hospital San Antonio', 'En el recorrido se observaron fallas de diseño en la circulación del personal médico, los quirófanos (áreas gris/blanca) y el manejo de residuos biológicos, que se mezclan con la circulación general del hospital. El alcalde pidió contratar un especialista en infraestructura hospitalaria —no solo el fiscal de obra civil— para determinar qué se puede corregir todavía.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Emitir informe oficial sobre las modificaciones contractuales del Hospital San Antonio y determinar responsables de los cambios', 'Entre los tres contratos de la obra se detectaron cambios sucesivos en las especificaciones técnicas (colores, materiales, diseño de flujos) sin que quede claro quién los autorizó. El alcalde adelantó que, tras evaluar con el equipo técnico, se emitirá un informe oficial sobre lo ocurrido.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Concluir la construcción del Hospital San Antonio pese al retraso frente al plazo comprometido', 'La obra del Hospital San Antonio lleva casi seis años y va por su tercer contrato (cerca de Bs 71 millones), con un avance de 50% físico y 39% financiero. La fecha comprometida de conclusión es el 21 de septiembre de 2026, pero en la inspección se reconoció que no se llegará a esa fecha por atrasos en importaciones de equipos y por el ajuste de precios ante la subida del dólar. El alcalde pidió definir un nuevo cronograma y revisar el mecanismo de actualización de precios (Decreto) para no perder más tiempo.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Presentar la estimación del impacto económico de la verbena paceña', 'Consultado sobre cuánto aportaría la verbena a la reactivación económica de la ciudad, el alcalde reconoció no contar aún con una cifra y se comprometió a entregar posteriormente una estimación del impacto económico del evento en la ciudad.', NULL, NULL, 'En revisión', '⚪', 'Media', NULL, 'Despacho', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Programar reuniones con las caseras para distribuir espacios durante la verbena', 'Para evitar conflictos por puestos y lugares de venta, como ha ocurrido en ediciones pasadas, el municipio organizará reuniones con las comerciantes y caseras de los mercados aledaños a la Plaza San Francisco para acordar de manera dialogada la distribución de espacios durante la verbena.', NULL, NULL, 'En revisión', '🔴', 'Media', '2026-07-13', 'Despacho', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Contratar baños públicos para la verbena paceña', 'Siguiendo la recomendación de la Iglesia Católica sobre la falta de servicios higiénicos en eventos masivos anteriores, el municipio gestiona la contratación de baños públicos portátiles para la verbena en la Plaza San Francisco.', 16, 'EJE-06', 'Vigente', '🔴', 'Media', '2026-07-14', 'Despacho', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Instalar una valla de protección para el muro patrimonial de la iglesia de San Francisco', 'A solicitud de la Iglesia Católica, preocupada por el contacto directo del público con el muro histórico durante la verbena, el municipio instalará una barrera de protección para resguardar esa infraestructura patrimonial mientras dura el evento.', NULL, NULL, 'En revisión', '🔴', 'Alta', '2026-07-14', 'Despacho', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values (NULL, 'Coordinar el despliegue de seguridad para la verbena paceña', 'Para garantizar el orden durante las 13 horas continuas de la verbena en la Plaza San Francisco, el municipio articula un operativo conjunto que suma a la Guardia Municipal reforzada, la Policía Boliviana, el grupo SAR y la Policía Militar. El alcalde detalló este despliegue al responder sobre las medidas de seguridad del evento.', NULL, NULL, 'En revisión', '🔴', 'Alta', '2026-07-15', 'Despacho', NULL, NULL, NULL, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C083', 'Intervención y mejora de la infraestructura del Teatro al Aire Libre', 'El Teatro al Aire Libre necesita una intervención de fondo, con transformaciones sustanciales al escenario y sus instalaciones. El alcalde la respaldó como compromiso paraguas entre Culturas e Infraestructura, dejando la cobertura/techo para la próxima gestión. Proyecto y plazo por definir.', 91, 'EJE-06', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Teatro al Aire Libre, La Paz', '-16.5035,-68.1276', NULL, 'Dijo el alcalde: "de una vez hay que hacer un proyectito… se van a hacer transformaciones sustanciales en el Teatro al Aire Libre."');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C082', 'Crear el reglamento de asignación de escenarios municipales (riesgo compartido)', 'No hay reglas para asignar los escenarios municipales: la gestión anterior los repartió ''a dedo'' y la programación solo está cubierta hasta julio. El alcalde dispuso crear un reglamento con un mecanismo de ''riesgo compartido'' y convocar a los artistas.', 84, 'EJE-06', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Teatro al Aire Libre, La Paz', '-16.5035,-68.1276', NULL, 'Dijo el alcalde: "no hay ningún reglamento que define la forma de asignación… ya estamos trabajando en la reglamentación, hemos hecho el corte hasta julio, de ahí en adelante no existe ninguna programación." | [2026-05-15] abrir los centros culturales municipales (cine 6 de Agosto, Teatro al Aire Libre) de forma permanente para ensayos, bajo modelo de riesgo compartido.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C081', 'Agilizar la designación del Director de la Banda Municipal', 'La Banda Municipal sigue sin director. Se planteó agilizar la designación —se mencionó a un candidato con trayectoria en las FF.AA.—, pero el alcalde prefirió no cerrarla todavía (''lo hablamos después'').', NULL, 'EJE-06', 'En revisión', '⚪', 'Media', NULL, 'Territorio', 'Teatro al Aire Libre, La Paz', '-16.5035,-68.1276', NULL, 'Dijo el alcalde: "eso lo hablamos después… esos temas lo hablamos." (Solicitud: "pediría que se agilice esa situación para que tengamos director".)');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C080', 'Gestionar ambiente propio e institucionalización de la Banda Eduardo Caba', 'Pese a sus más de 70 años, la Banda Eduardo Caba nunca fue institucionalizada ni tiene ambiente propio: hoy se acomoda en espacios prestados. El alcalde respaldó gestionarle un espacio propio y su institucionalización, como objetivo de largo alcance.', 88, 'EJE-06', 'Vigente', '🟢', 'Baja', '2026-11-30', 'Territorio', 'Teatro al Aire Libre, La Paz', '-16.5035,-68.1276', NULL, 'Dijo el alcalde: "quisiera ver la posibilidad… a futuro… el ambiente propio de la banda… más de 70 años y no estamos ni siquiera institucionalizados."');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C079', 'Reparar el bus de la Banda y evaluar un segundo bus', 'El bus de la banda —21 asientos para 38 integrantes— tiene el motor tan deteriorado que deben empujarlo para arrancar. El alcalde pidió repararlo y evaluar un segundo bus para asistencias simultáneas. NOTA: aunque surgió en el contexto de Culturas, un bus es gestión vehicular/logística — responsable por confirmar.', 88, 'EJE-08', 'Vigente', '⚪', 'Media', NULL, 'Territorio', 'Teatro al Aire Libre, La Paz', '-16.5035,-68.1276', NULL, 'Dijo el alcalde: "lo incorporamos en todos los requerimientos y poco a poco vamos a ir resolviendo." (Solicitud: "solicitamos que repare inmediatamente… el motor está mal directamente".)');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C078', 'Dotar de uniformes nuevos a la Banda Municipal', 'Para la presentación del 16 de julio la banda usará el uniforme actual; el alcalde dejó los uniformes nuevos para después. El requerimiento de los nuevos ya está presentado ante la Secretaría de Culturas.', 88, 'EJE-06', 'Vigente', '🟢', 'Media', '2026-08-29', 'Territorio', 'Teatro al Aire Libre, La Paz', '-16.5035,-68.1276', NULL, 'Dijo el alcalde: "vamos a tener que aguantar este 16 de julio con el uniformecito que tenemos, y ya vamos a ver después más adelante."');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C077', 'Restituir el POA exclusivo de la Banda Municipal Eduardo Caba', 'El POA exclusivo de la Banda Municipal desapareció (''refundido'') en la gestión anterior, y sin él la banda quedó sin uniformes, instrumentos, atriles ni bus. El alcalde se comprometió a restituirlo tras revisar los reportes del corte de 60 días (cronograma 30-60-90).', 84, 'EJE-06', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Teatro al Aire Libre, La Paz', '-16.5035,-68.1276', NULL, 'Dijo el alcalde: "yo le pedí a la secretaria que se restituya esa parte del POA para la banda… ese es un compromiso, o sea que decirlo vamos a hacer."');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C075', 'Compartir con el equipo los documentos del estudio de la marca ciudad ''La Paz, Capital del Cielo''', 'El alcalde mencionó el estudio de más de un año que sustenta la marca ciudad ''La Paz, Capital del Cielo'' y su isotipo (turismo de altura), y comprometió compartir esos documentos con el equipo del gobierno municipal para alinear el trabajo del centro histórico con esa visión.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C076', 'Buscar una alternativa para el ordenamiento de cables en las fachadas del centro histórico', 'Como parte de la recuperación del centro histórico, el alcalde pidió estudiar una alternativa para ordenar y retirar los cables sobrepuestos en las fachadas patrimoniales, que afean el ingreso a la ciudad.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C064', 'Definir fases y buscar padrinos para el pintado de fachadas patrimoniales del tramo Montes–Pérez Velasco', 'Prueba piloto del programa Padrinos del Patrimonio: definir fases y plazos y conseguir padrinos/aliados estratégicos que financien el pintado de fachadas de aproximadamente 12 inmuebles patrimoniales del tramo de la avenida Montes a Pérez Velasco, dado que el gobierno municipal no tiene recursos para la restauración completa.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C065', 'Socializar con los negocios la propuesta de letrero único en inmuebles patrimoniales', 'El alcalde pidió que, antes de aplicar el letrero único (panel modular por rubro) en los inmuebles patrimoniales del centro histórico, se socialice y se converse con los propietarios de los negocios para lograr acuerdo en lugar de imponerlo. Área del proyecto: Padrinos del Patrimonio, tramo avenida Montes–Pérez Velasco.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C066', 'Mostrar en dos semanas el software de trámites digitales desde el celular', 'En el marco de la ciudad digital (sin fotocopias, interoperabilidad con el SEGIP), el alcalde anunció que en las próximas dos semanas se mostrará el software y las aplicaciones para hacer los trámites municipales desde el celular.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C067', 'Desarrollar un programa de apoyo a padres y niños con TDAH y autismo', 'Ante el pedido de una madre en la piscina, el alcalde comprometió trabajar un programa para apoyar a los padres y a los niños con TDAH y autismo en la parte educativa y deportiva.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C068', 'Volver la próxima semana a ver la demostración de gimnasia y jugar ajedrez con las escuelas', 'Compromiso público del alcalde (''trato hecho''): regresar la próxima semana a la piscina de Obrajes para ver la demostración de las niñas de gimnasia y jugar una partida con la escuela municipal de ajedrez, y revisar el avance de las escuelas deportivas.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C069', 'Levantar inventario y ordenar los almacenes de material deportivo de Obrajes', 'Se observó desorden en los almacenes y depósitos de material deportivo de la piscina; el alcalde pidió ordenarlos y levantar inventario de los equipos (incluye el material de las escuelas de taekwondo).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C070', 'Gestionar recursos para reparar la piscina, el área de gimnasia y la cancha de básquet', 'El alcalde anunció que está consiguiendo los recursos para cambiar/reparar la piscina, la parte de gimnasia y la cancha de básquetbol de Obrajes, que están deterioradas, y pidió paciencia mientras se ejecuta.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C071', 'Resolver la conexión de gas de la piscina de Obrajes', 'Tarea pendiente desde hace 60 días: falta la conexión de gas de la piscina de Obrajes. El alcalde pidió destrabarla como parte del mantenimiento de infraestructura observado.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C072', 'Trasladar las máquinas del predio de Obrajes el viernes', 'Se comprometió el traslado de las máquinas el viernes, con participación de todo el equipo y de la Secretaría de Ciudad y Hábitat, como parte del ordenamiento del predio observado en la inspección.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C073', 'Habilitar el salón interior de Obrajes para zumba y yoga de la tercera edad', 'El alcalde comprometió habilitar esta semana un salón interior de la piscina de Obrajes para que las personas de la tercera edad hagan zumba y yoga bajo techo, dado el frío para hacerlo en la plaza. Se estima participación de entre 40 y 50 años y hasta 20 personas por sesión.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C074', 'Instalar baranda de seguridad en la zona insegura de la piscina de Obrajes', 'Durante la inspección de la inauguración, el alcalde observó una zona insegura (grada/borde) donde podrían caerse los niños e instruyó colocar una baranda ese mismo día. Ubicación: piscina olímpica de Obrajes.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C059', 'Retornar el árbol de Navidad a la Plaza de San Francisco', 'Ante el pedido de una vecina a la salida de la misa (''puede volver el árbol de Navidad de aquí a San Francisco''), el alcalde respondió: ''Tenemos que volver''. Compromiso para la temporada navideña 2026.', 84, 'EJE-06', 'Vigente', '🟢', 'Baja', '2026-12-15', 'Territorio', 'Plaza San Francisco, La Paz', '-16.4967,-68.1382', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C058', 'Coordinar con la Asociación de Folkloristas un programa para posicionar la marca ciudad', 'El alcalde planteó armar un programa integral con la Asociación de Folkloristas (no negociar evento por evento) que ayude a posicionar la marca ciudad ''La Paz, Capital del Cielo''. La directiva de la asociación, que está en Santa Cruz, llega el 27 de julio; ese día no hay aún ningún evento con ellos en la agenda: falta agendar la reunión.', 92, 'EJE-06', 'Vigente', '🔴', 'Media', '2026-07-27', 'Territorio', 'Plaza San Francisco, La Paz', '-16.4967,-68.1382', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C057', 'Realizar la verbena paceña en la Plaza Mayor de San Francisco cuidando el patrimonio', 'El alcalde confirmó que la verbena por las fiestas julias vuelve a San Francisco: la inspección del equipo técnico especializado verificó que el embovedado soporta eventos de gran magnitud. El escenario se levantará desplazado del atrio, apuntando hacia la Av. Mariscal Santa Cruz, para conservar el patrimonio de la iglesia, con un esquema de limpieza ''estilo japonés'' de cuidado del espacio público. En la agenda del 15 de julio figura la ''Gran serenata a La Paz'' en la Plaza Mayor de San Francisco (20:00).', 88, 'EJE-06', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Plaza San Francisco, La Paz', '-16.4967,-68.1382', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C056', 'Bailar con los caporales en su próxima presentación', 'Compromiso personal del alcalde con el grupo de caporales presente en la activación de la ciclovía: ensayar y bailar con ellos en su próxima presentación (mencionó además un compromiso previo con la Morenada). Fecha tentativa relacionada: Pre Entrada del Gran Poder, 26 de julio.', 24, NULL, 'Vigente', '🔴', 'Baja', '2026-07-26', 'Territorio', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C055', 'Habilitar las Escuelas Municipales de Deportes de vacaciones: 40 puntos y 7 disciplinas', 'Anuncio e invitación del alcalde: durante las vacaciones se habilitan 40 puntos con 7 disciplinas (fútbol, voleibol, básquetbol, natación, gimnasia, ajedrez y una más) en las Escuelas Municipales de Deportes, con inscripciones y sedes publicadas en la página web del gobierno municipal.', 54, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-07-07', 'Territorio', 'Av. del Poeta y Costanera (ruta ciclovía recreativa), La Paz', '-16.5042,-68.1276', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C054', 'Segunda fase de recuperación: Parque Urbano Central y remozamiento de Laikacota', 'Tras la reapertura del parque Laikacota (4 de julio), el alcalde anunció la segunda fase: recuperar todo el Parque Urbano Central —churrasqueras, ciclovías, senderos para caminar y áreas para danza y baile— y, concluida esa fase, volver al parque Laikacota para remozarlo como corresponde.', 121, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Av. del Poeta y Costanera (ruta ciclovía recreativa), La Paz', '-16.5042,-68.1276', 0, '[2026-06-08 · SETRAM Parque Urbano Central] Se constató que la estructura (tinglado/mirador) del Parque Urbano Central, que costó mucho, está cerrada y sin utilización; se debe evaluar su estado estructural (desequilibrio de la estructura metálica) y habilitarla para darle uso.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C053', 'Entregar las plazas al folklore como espacios de ensayo', 'Proyecto anunciado por el alcalde: habilitar plazas de la ciudad como espacios formales de ensayo para las fraternidades y grupos folklóricos, con punto de energía eléctrica (''el enchufe'') y condiciones adecuadas, para que no se les decomise el equipo de sonido cuando ensayan en el espacio público.', 84, 'EJE-06', 'Vigente', '🟢', 'Media', '2026-08-31', 'Territorio', 'Av. del Poeta y Costanera (ruta ciclovía recreativa), La Paz', '-16.5042,-68.1276', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C052', 'Mesa de diálogo con ciclistas y fraternidades folklóricas para recibir sus propuestas', 'El alcalde comprometió públicamente a ambos grupos presentes (asociación de ciclistas y grupo de caporales) a una primera reunión de diálogo para que traigan sus propuestas y proyectos, bajo la premisa de que las decisiones del gobierno municipal deben construirse en diálogo con la gente.', 112, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-07-17', 'Territorio', 'Av. del Poeta y Costanera (ruta ciclovía recreativa), La Paz', '-16.5042,-68.1276', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C051', 'Replantear y mejorar las ciclovías de la ciudad junto a la asociación de ciclistas', 'Compromiso del alcalde en la activación de la ciclovía: reunirse esta misma semana con la asociación de ciclistas para replantear la ciclovía principal del centro, que no está en buenas condiciones de ruta ni de seguridad, evaluando incluso su reubicación. El objetivo es construir ''verdaderas ciclovías'' con condiciones de seguridad, habilitar rutas en otros macrodistritos y sostener las ciclovías recreativas todos los fines de semana, para que a futuro la gente pueda ir a su trabajo en bicicleta.', 112, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-07-12', 'Territorio', 'Av. del Poeta y Costanera (ruta ciclovía recreativa), La Paz', '-16.5042,-68.1276', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C050', 'Reponer las impresoras y el equipamiento informático del Centro de Salud El Vergel', 'Reclamo de la doctora de medio tiempo recogido en la visita: las impresoras no funcionan (una impresora de cinta ''en sus últimos respiros'') pero el SUS exige enviar impresiones, referencias impresas y boletas; sin los medios, el médico pierde 3-4 minutos por paciente o no puede cumplir. El alcalde señaló en la visita que el equipamiento de los centros ''lo estamos viendo ahora''. Reponer el equipamiento de impresión e informático del centro.', 51, 'EJE-02', 'Vigente', '⚪', 'Media', NULL, 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C049', 'Atender el caso del perro comunitario y la jauría de perros en El Vergel', 'Compromiso del alcalde con la vecina protectora Nicolía (Virginia) González (tel. 73665383): la contactará con Bianca (responsable del área de bienestar animal/zoonosis) para atender el caso del perro comunitario de la zona, que fue maltratado (le quemaron la casita dos veces, le echaron vidrio cortado, fue atropellado y tiene la cadera lastimada) y no se deja tocar, por lo que requiere especialistas que logren ganarse su confianza. Los vecinos reportan además jaurías de perros abandonados que muerden a los vecinos en las 12 zonas del centro de salud.', 80, 'EJE-05', 'Vigente', '⚪', 'Media', NULL, 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C048', 'Programa La Paz Iluminada: recambio de más de 130.000 luminarias LED en la ciudad', 'Anunciado por el alcalde en la visita ante el reclamo de que la zona del centro de salud es muy oscura: el proyecto La Paz Iluminada cambiará todas las luces de la ciudad a luminarias LED — canchas, parques, accesos y aceras, más de 130.000 luminarias — en etapas. La iluminación del entorno del Centro de Salud El Vergel entrará en este programa.', 105, 'EJE-08', 'Vigente', '⚪', 'Alta', NULL, 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C047', 'Mejorar la seguridad vial y la accesibilidad peatonal del acceso al Centro de Salud El Vergel', 'Instrucción del alcalde al cierre del recorrido: el acceso al centro no es adecuado. Primero, seguridad vial: cuesta cruzar la avenida de alta velocidad que está al frente — evaluar un reductor de velocidad (rompemuelles) o semáforo para un cruce peatonal seguro que reduzca la velocidad vehicular en la vía. Segundo, accesibilidad universal: el paso actual de ingreso no sirve — no entra ni una camilla ni una silla de ruedas (hay que ladear al enfermo con riesgo de caída); habilitar una entrada peatonal por la puerta del otro lado, levantar las rejas de la construcción en desuso (una pared la reemplaza) y dejar dos puertas: una de ingreso de pacientes y otra de servicio para sacar la basura. Considerar también que la gente hace fila en la calle desde las 4-5 de la mañana y queda afuera.', 113, 'EJE-08', 'Vigente', '⚪', 'Alta', NULL, 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C046', 'Dotar personal y especialidades al Centro de Salud El Vergel', 'Demanda de los vecinos recogida en la visita: el centro atiende 12 zonas con una sola doctora de tiempo completo (Dra. Marioli, 30-35 pacientes/día sin tiempo para informes), una doctora de medio tiempo (Dra. Vivian, odontología) y una sola enfermera que no abastece (toma signos vitales para odontología y medicina general a la vez). Piden ginecología (mamás gestantes sin atención especializada), pediatría (niños atendidos solo por medicina general, incluidos niños con discapacidad que requieren más dedicación) y al menos una enfermera adicional. Con la ampliación de horarios a 12 horas prevista en la transformación del sistema, se requerirá dotar este personal.', 50, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C045', 'Gestionar ante el SEDES el cambio de la normativa de registros manuales en salud', 'El alcalde constató en la visita que el registro de vacunas y los expedientes siguen siendo manuales (libro físico) por normativa, duplicando el trabajo aunque exista sistema digital, con pérdida de tiempo del personal médico. Compromiso: hablar con el SEDES para ver si se puede cambiar la normativa e integrar estos registros al nuevo sistema digitalizado.', 143, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C044', 'Garantizar el abastecimiento de medicamentos en los centros de salud', 'Los vecinos reclamaron que la farmacia del centro no tiene medicamentos. El equipo municipal informó que la distribución de medicamentos ya empezó esta semana (lunes y martes) y continúa. El alcalde señaló además el problema de la compra: hay laboratorios que ofertan a buen precio pero entregan la peor marca, por lo que hay que mejorar el control de calidad en las adquisiciones. Incluye la dotación de insumos de bioseguridad (barbijos, lavado de manos) para pacientes sin recursos.', 51, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, '| [2026-07-23 · Tembladerani] el centro rechazó medicamentos por un tema administrativo de pago; cajas sin medicamento y semaforización roja (vencidos). Destrabar el pago y aplicar la semaforización.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C043', 'Programa de salud preventiva domiciliaria para adultos mayores', 'Compromiso del alcalde ante el reclamo de que los adultos mayores hacen fila desde las 4 de la mañana por una ficha y por el complemento nutricional Carmelo (solo 10-20 fichas por día): se está construyendo la base de datos de todos los adultos mayores (dónde viven y en qué situación están) para que el médico vaya a su casa, el Carmelo se les entregue a domicilio y se les gestione la ficha para sus controles preventivos (diabetes, hipertensión). Trabajo coordinado con otras secretarías. Objetivo: que los adultos mayores ya no tengan que madrugar a hacer fila.', 51, 'EJE-02', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, '[2026-05-06 · Hospital La Portada] El alcalde planteó el modelo de atención domiciliaria segmentada, extendiéndolo a personas con discapacidad además de adultos mayores: «nos vamos a atender a las personas con discapacidad en su casa y a los adultos mayores... vamos a hacer la segmentación». Refuerza y amplía este programa. | [2026-07-23 · Tembladerani] «a nuestros abuelitos los tenemos que ir a buscar en su casa... el médico va a ir»; levantar censo domiciliario de adultos mayores.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C042', 'Ampliar la cobertura de la red municipal de salud con el convenio Nuestra Señora de La Paz', 'El alcalde anunció en la visita que el convenio con el hospital privado Nuestra Señora de La Paz ya está cerrado: pasará a ser parte de la red municipal de salud, ampliando la cobertura de los servicios de salud para los vecinos, en el marco del nuevo modelo que integra centros de salud públicos y privados de primer y segundo nivel en las redes de salud.', 51, 'EJE-02', 'Vigente', '🟢', 'Alta', '2026-11-30', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C041', 'Implementar la transformación del sistema municipal de salud en las 5 redes hasta noviembre', 'Explicado por el alcalde y el secretario de salud en la visita: el proyecto piloto de la ''revolución de la salud'' arrancó el 3 de julio en la red 5 (zona Sur) y corre hasta fin de mes; con las lecciones aprendidas se extenderá a las redes 4, 3, 2 y 1, terminando las 5 redes hasta noviembre. Incluye: desaparición de las fichas de papel (ficha desde el celular), interoperabilidad y conexión entre todos los centros de salud de primer y segundo nivel incluidos privados, historial médico digitalizado, derivaciones directas del centro de salud al especialista sin hacer fila en el hospital, cruce de base de datos del SUS para que el paciente sea atendido en cualquier red aunque haya cambiado de domicilio, y ampliación de horarios: los centros de 6 horas pasan a 12 y los de 12 a 24. Participan gobierno municipal, gobierno nacional (Ministerio de Salud), gobernación y SEDES.', 153, 'EJE-02', 'Vigente', '🟢', 'Crítica', '2026-11-30', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, '[2026-05-12 · Hospital Municipal La Paz] El alcalde detalló componentes de esta transformación (salud 4.0): convertir los 67 centros de salud a 24/7, una red de derivación entre niveles (incluso a privados con capacidad ociosa), y la incorporación de telemedicina e inteligencia artificial para informes y atención inicial, empezando por el hospital-escuela.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C040', 'Ampliar y reorganizar los espacios del Centro de Salud El Vergel', 'El centro atiende 12 zonas con espacios insuficientes: el consultorio funciona también como depósito, falta al menos uno o dos consultorios adicionales, y la ducha del personal está inutilizada porque el ambiente se usa de depósito. El alcalde instruyó en sitio buscar un depósito para liberar la ducha (''¿por qué no sacamos todo del depósito? Hay que buscar un depósito''). Incluye revisar el manejo de residuos (los tachos y bolsas se depositan en el patio) y el depósito de la farmacia que quedó sin implementar tras la refacción anterior. Los vecinos piden además la ampliación general del centro por la alta demanda (tienen hasta un libro de actas de la junta con esa solicitud histórica).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C039', 'Refacción del techo y poda periódica del árbol del Centro de Salud El Vergel', 'Mantenimiento de la infraestructura y el equipamiento urbano del centro de salud: el árbol contiguo bota hojas y semillas todos los días, llena las canaletas y ya provocó goteras y la caída del cielo raso en dos ocasiones (de noche, sin heridos). La poda esporádica no alcanza: se necesita poda programada con frecuencia regular (áreas verdes), limpieza de canaletas y la refacción del techo y cielo raso dañados. La portera incluso solicitó una escalera para limpiar ella misma el techo.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C038', 'Enviar sillas de espera para los pacientes del Centro de Salud El Vergel', 'Compromiso directo del alcalde durante el recorrido: el doctor pidió sillas para el área de espera de pacientes en la planta alta y el alcalde comprometió el envío inmediato (''ya tenemos sillitas, vamos a mandar'').', 51, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-07-10', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C037', 'Reparar el sistema eléctrico y la iluminación del Centro de Salud El Vergel', 'Compromiso directo del alcalde en la visita: enviar a uno del equipo de eléctricos al centro de salud. El consultorio no tiene luz, las luminarias interiores no funcionan, el baño del personal no tiene luz y los focos perimetrales exteriores tampoco funcionan (la falla parece interna: ya se repusieron focos y siguen sin encender). La portera se alumbra con una radio-linterna que trae de su casa.', 51, 'EJE-07', 'Vigente', '🔴', 'Alta', '2026-07-11', 'Territorio', 'Centro de Salud El Vergel (Bajo Llojeta, Av. Mario Mercado), La Paz', '-16.5336,-68.1384', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C036', 'Crear la identidad musical de la marca ciudad y de los videos municipales', 'Instrucción del alcalde: la marca ciudad «La Paz, Capital del Cielo» debe tener su propia música, y los videos municipales una identidad sonora por tipo de contenido, porque la comunicación es emoción y la música conecta con la gente. Definido como necesario aunque no inmediato (el alcalde: ahorita no, pero debe tener).', 92, 'EJE-06', 'Vigente', '🔴', 'Media', '2026-07-31', 'Gabinete', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C035', 'Montar el sistema de escucha social (sondeos y lectura de comentarios)', 'Conectarse con la percepción real de la gente mediante encuestas, sondeos y lectura sistemática de los comentarios en redes (distinguiendo bots de cuentas reales), en reemplazo de las brigadas de enlaces en subalcaldías que el alcalde desestimó. Los mensajes espontáneos de la gente alimentan la narrativa de la comunicación municipal.', 8, 'EJE-01', 'Vigente', '🔴', 'Media', '2026-07-31', 'Gabinete', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C034', 'Crear la sala de crisis comunicacional', 'Conformar una sala de crisis con gente que analice y responda comunicacionalmente en el momento ante escándalos o ataques: clasificación del nivel de riesgo, mensajes de respuesta y vocería. Validada por el alcalde como segunda prioridad: primero concentrarse en producir; la contención de crisis se organiza en paralelo.', 8, 'EJE-01', 'Vigente', '🔴', 'Media', '2026-07-31', 'Gabinete', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C033', 'Definir la estrategia comunicacional frente al pedido de revocatorio', 'Anticiparse (no reaccionar): posicionar desde ahora que quienes promueven el discurso del revocatorio son los afectados por el desmontaje de las mafias — ítems fantasmas, patentes y boliches, venta de pegas y extorsión a vecinos — y comunicar permanentemente lo que la gestión está haciendo, de modo que cuando alguien lo plantee quede conectado con esos intereses.', 8, 'EJE-01', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Gabinete', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C031', 'Ejecutar el plan de comunicación del programa de aniversario (31 días, 165 actividades)', 'Instrucción directa del alcalde: durante los 31 días de julio, cada una de las 165 actividades del programa de aniversario debe comunicarse en tres momentos — expectativa previa, cobertura del día y post posterior — (al menos 3 piezas por actividad, unas 500 piezas en el mes). Es la prioridad del equipo de comunicación en julio, por encima de cualquier otra iniciativa; sin piezas hechas solo por cumplir: primero el gancho, luego el contenido.', 8, 'EJE-01', 'Vigente', '🔴', 'Media', '2026-07-31', 'Gabinete', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C030', 'Rediseñar la estrategia de comunicación municipal con enfoque proactivo', 'El alcalde rechazó la estrategia presentada por carecer de objetivo claro e instruyó reelaborarla: definir con claridad qué se quiere comunicar y cómo comunicarlo, con enfoque proactivo (la alcaldía propone y marca la agenda, no reacciona a los ataques) y conectada con la gente. La directora de comunicación se comprometió a trabajar una nueva estrategia enmarcada en comunicar y acercar.', 8, 'EJE-01', 'Vigente', '🔴', 'Alta', '2026-07-10', 'Gabinete', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C029', 'Reponer el control de tránsito y reforzar la Defensoría de la Niñez en la Terminal Minasa', 'Gestionar ante Tránsito la reposición del control que fue eliminado desde la pandemia de COVID-19, y reforzar la cobertura de la Defensoría de la Niñez y Adolescencia en la Terminal Minasa (hoy con una sola persona hasta las 17:00, frente a una operación que va hasta la madrugada) para el control de permisos de viaje de menores, especialmente en la temporada alta de viajes.', 77, 'EJE-05', 'Vigente', '🔴', 'Media', '2026-08-01', 'Territorio', 'Terminal Minasa (Villa Fátima), La Paz', '-16.4810,-68.1190', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C028', 'Mejorar las condiciones del comedor y los puestos de las comerciantes de Minasa', 'Intervenir para mejorar las condiciones precarias del comedor y los puestos de las comerciantes de la Terminal Minasa (espacio más amplio, iluminado, higiénico y digno), dado que es donde comen los viajeros y turistas que se dirigen al norte del departamento. Trabajo conjunto entre la dirección de la terminal y las comerciantes.', 112, 'EJE-08', 'Vigente', '🟡', 'Media', '2026-08-08', 'Territorio', 'Terminal Minasa (Villa Fátima), La Paz', '-16.4810,-68.1190', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C027', 'Reunirse con el sector transporte y el sector comercio de la Terminal Minasa', 'Una vez definidos el estudio y el proyecto, convocar a reuniones con los transportistas, sindicatos, comerciantes y usuarios de la Terminal Minasa para presentar la propuesta, consensuar mejoras y suscribir un nuevo acuerdo que supere el convenio de 2012 y el carácter provisional de la terminal.', 112, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-29', 'Territorio', 'Terminal Minasa (Villa Fátima), La Paz', '-16.4810,-68.1190', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C026', 'Buscar un terreno alternativo para la Terminal Minasa', 'Si el estudio determina que el terreno actual no ofrece condiciones o que mejorarlo resulta demasiado costoso, buscar de forma proactiva un terreno alternativo (aproximadamente 50.000 m²) para reubicar la Terminal Minasa. El alcalde instruyó no limitarse a enviar notas, sino gestionar y acercarse a las instancias correspondientes para identificar el predio.', 112, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-08-15', 'Territorio', 'Terminal Minasa (Villa Fátima), La Paz', '-16.4810,-68.1190', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C025', 'Elaborar el proyecto de la nueva Terminal Minasa con un especialista en terminales', 'Desarrollar el proyecto de arquitectura e ingeniería de una nueva Terminal Minasa con un especialista en terminales de transporte, gestionado vía cooperación internacional (p. ej. Cosoliz). El diseño debe dimensionarse con una proyección de demanda a 10 años y sustento técnico (no estimaciones improvisadas), dejar proyectada una estación de teleférico para conectar con la red (hacia la plaza Villarroel) y una conexión adecuada y segura con el mercado contiguo. Busca reemplazar el carácter provisional de la terminal por una infraestructura definitiva y planificada.', 112, 'EJE-08', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Terminal Minasa (Villa Fátima), La Paz', '-16.4810,-68.1190', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C024', 'Emitir un informe técnico-legal sobre el convenio 2012 con los transportistas de Minasa', 'Esclarecer la situación contractual del sector transporte en la Terminal Minasa: el convenio suscrito en la gestión 2012 supuestamente exime del pago mientras la terminal sea provisional, pero eso no consta por escrito en el contrato. Actualmente solo 18 de las empresas autorizadas pagan. Elaborar un informe técnico-legal que aclare las obligaciones de cobro y sustente la renegociación de un nuevo acuerdo.', 112, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-07-18', 'Territorio', 'Terminal Minasa (Villa Fátima), La Paz', '-16.4810,-68.1190', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C023', 'Realizar el estudio geológico y de suelos del terreno de la Terminal Minasa', 'Instrucción del alcalde en la inspección: verificar las condiciones del terreno de la Terminal Minasa (relleno de más de 30 m sin consolidación planificada, nivel freático, capacidad portante y grado de compactación) para determinar si es viable construir infraestructura nueva en el sitio o si resulta demasiado costoso. Coordinar con los ingenieros/geólogos (ing. Tirini e ing. Toro). Es el primer paso, previo a cualquier proyecto.', 112, 'EJE-08', 'Vigente', '🔴', 'Alta', '2026-07-23', 'Territorio', 'Terminal Minasa (Villa Fátima), La Paz', '-16.4810,-68.1190', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C022', 'Organizar la carrera pedestre 5K, 10K y 21K de las fiestas julias', 'Organizar la actividad deportiva y carrera pedestre de 5K, 10K y 21K por las fiestas julias, convocando a las unidades educativas y a la ciudadanía, como parte del deporte recreativo del aniversario.', 50, 'EJE-02', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Plaza Alonso de Mendoza (Churubamba), La Paz', '-16.4925,-68.1395', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C021', 'Reglamentar e iniciar el embanderamiento de la ciudad de La Paz', 'Iniciar el embanderamiento de la ciudad y presentar la resolución que reglamenta la ley por la cual los ciudadanos, actividades económicas y comercios deben embanderar La Paz con la bandera paceña en lugares visibles, como identidad cívica de las fiestas julias.', 66, 'EJE-04', 'Vigente', '🔴', 'Media', '2026-07-01', 'Territorio', 'Plaza Alonso de Mendoza (Churubamba), La Paz', '-16.4925,-68.1395', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C020', 'Lanzar el programa de Turismo de Altura (hub del turismo andino)', 'Iniciar el programa de Turismo de Altura para convertir a La Paz en el hub del turismo andino, multiplicar los visitantes y las noches de estadía, y promocionar la ciudad y el país como destino turístico. Uno de los programas más importantes de la gestión.', 86, 'EJE-06', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Plaza Alonso de Mendoza (Churubamba), La Paz', '-16.4925,-68.1395', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C019', 'Iniciar el programa de mejoramiento de calles de La Paz', 'Arrancar el programa de mejoramiento de calles y vías de la ciudad: pavimentación, mantenimiento vial e infraestructura urbana en los barrios.', 104, 'EJE-07', 'Vigente', '🟢', 'Media', '2026-09-30', 'Territorio', 'Plaza Alonso de Mendoza (Churubamba), La Paz', '-16.4925,-68.1395', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C018', 'Iniciar la industrialización de los residuos sólidos', 'Poner en marcha el proyecto de industrialización de los residuos sólidos de la ciudad, con enfoque de economía circular y aprovechamiento/tratamiento de la basura, coordinado con cooperación internacional.', 127, 'EJE-09', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Plaza Alonso de Mendoza (Churubamba), La Paz', '-16.4925,-68.1395', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C017', 'Iniciar el proyecto de Ciudad Inteligente', 'Lanzar el proyecto de ciudad inteligente para La Paz: tecnología, digitalización, sensores y datos para la gestión urbana y la innovación en los servicios municipales.', 57, 'EJE-03', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Plaza Alonso de Mendoza (Churubamba), La Paz', '-16.4925,-68.1395', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C016', 'Iniciar el cambio de luminarias a luces LED en la ciudad de La Paz', 'Poner en marcha el proyecto de cambio de luminarias del alumbrado público a luces LED en la ciudad, para eficiencia energética e iluminación de calles y espacios públicos, coordinado con el gobierno nacional y cooperación internacional.', 105, 'EJE-07', 'Vigente', '🟢', 'Alta', '2026-09-30', 'Territorio', 'Plaza Alonso de Mendoza (Churubamba), La Paz', '-16.4925,-68.1395', 0, '[2026-05-18 · recorrido Gran Poder] El alcalde detalló el alcance de ''La Paz iluminada'': de ~70.000 a 120.000-140.000 luminarias (casi el doble), con cámaras, sensores y fibra óptica/IoT; contrato a cerrarse este año.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C015', 'Cambiar el vidrio de la entrada de la oficina del despacho', 'Reponer el vidrio de la puerta de entrada de la oficina del despacho del alcalde. Mantenimiento de oficinas y servicios generales.', 24, NULL, 'Vigente', '🔴', 'Baja', '2026-07-10', 'Despacho', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C014', 'Presentar los más de 100 proyectos de ley municipales al Concejo', 'Presentar al Concejo Municipal los más de 100 proyectos de ley ya preparados por el Ejecutivo municipal para la transformación de la ciudad, una vez restablecido el funcionamiento del Concejo.', 18, 'EJE-01', 'Vigente', '🔴', 'Media', '2026-07-31', 'Despacho', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C013', 'Convocar a los 11 concejales al diálogo para restablecer el Concejo Municipal', 'Convocar formalmente a los 11 concejales a una reunión de diálogo (gobernabilidad y relación con el Concejo Municipal) para destrabar el conflicto institucional y restablecer el funcionamiento del Concejo conforme al reglamento del comité ad hoc y la sentencia constitucional, dejando de lado intereses personales.', NULL, 'EJE-01', 'Vigente', '🔴', 'Media', '2026-07-01', 'Despacho', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C012', 'Organizar los desfiles cívicos unificados del 14 y 15 de julio', 'Acto cívico protocolar y ceremonia de aniversario: realizar un solo desfile cívico el 14 y uno el 15 de julio, con un único palco oficial cada día, como parte de los actos de protocolo y la agenda de eventos del aniversario y las fiestas paceñas. Coordinación de protocolo entre gobierno nacional, departamental y municipal para evitar desfiles y palcos paralelos. El acto del 15 (efeméride departamental) es responsabilidad de la Gobernación, coordinado con el municipio.', 89, 'EJE-06', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Gabinete', NULL, NULL, 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C011', 'Presentar la Marca Ciudad de La Paz', 'Acto de presentación de la Marca Ciudad de La Paz (branding e identidad de la ciudad, economía naranja e industrias creativas) el 1 de julio en el Parque Laikacota, con invitados especiales y posible presencia del presidente.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C010', 'Reabrir al público el Parque Laikacota tras su reactivación', 'Abrir al público de punta a punta el Parque Laikacota, parque urbano, áreas verdes y espacio recreativo de la ciudad que estuvo cerrado y abandonado por años; reactivado con trabajo voluntario de funcionarios y donaciones de la comunidad. Reapertura ciudadana del parque, sus jardines y áreas verdes prevista para el sábado.', 121, 'EJE-09', 'Vigente', '🔴', 'Alta', '2026-07-04', 'Territorio', NULL, NULL, 0, '[2026-06-17 · inspección al Parque Laikacota] El parque está en abandono total: sin riego ni poda (vegetación seca, árboles cayendo), equipamiento desaparecido (bancas, sombrillas, basureros y los techos de resguardo), zonas de riesgo (fallas, tramos sin baranda, maderas con clavos) y sin actividades (ni el Año Nuevo Aymara). Las asociaciones del parque denuncian el mal trato y los cobros de EMAVERDE.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C009', 'Gestionar mecanismos de flexibilidad presupuestaria ante el tipo de cambio flexible', 'Gestionar ante el gobierno nacional (Ministerio de Economía y Finanzas, Banco Central de Bolivia y Ministerio de Planificación) mecanismos de flexibilidad en el manejo de los presupuestos subnacionales frente al nuevo tipo de cambio flexible que afecta los presupuestos municipales. Planteado y registrado en reunión con la Presidencia.', 33, 'EJE-01', 'Vigente', '🟢', 'Media', '2026-08-31', 'Gabinete', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C008', 'Reducir personal supernumerario e ítems fantasma en el servicio Pumakatari', 'Reducir el personal supernumerario del servicio Pumakatari (más de 60 personas) y eliminar los presuntos ítems fantasma que representaban 600 mil bolivianos mensuales, en el marco de la política de eficiencia y transparencia antes de plantear ajustes tarifarios a la ciudadanía.', 144, 'EJE-08', 'Vigente', '🟢', 'Alta', '2026-08-31', 'Territorio', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C007', 'Solicitar información a la empresa de recojo de residuos sólidos para evaluar sus tarifas', 'Solicitar por escrito información detallada a la empresa de aseo urbano que pide un incremento de tarifas adicional al de la indexación con la UFV, para transparentar sus datos y definir las medidas correspondientes sobre el servicio de recojo de basura.', 147, 'EJE-09', 'Vigente', '🔴', 'Alta', '2026-07-15', 'Territorio', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C006', 'Implementar ruta anti-trameaje y brigadas de reacción inmediata para el Pumakatari', 'Establecer una ruta y operativo anti-trameaje en coordinación con el sector del transporte, con una línea telefónica de denuncia habilitada y brigadas de reacción inmediata para verificar y sancionar el trameaje en las rutas del Pumakatari.', 144, 'EJE-08', 'Vigente', '🔴', 'Media', '2026-07-31', 'Territorio', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C005', 'Reprogramar el presupuesto para sostener el servicio Pumakatari hasta fin de año', 'Reprogramar el presupuesto del servicio de transporte municipal Pumakatari, cuyo presupuesto se agotó a fin de mes por la duplicación del precio del combustible (de menos de 4 a 9 bolivianos), para garantizar la continuidad del servicio hasta fin de año.', 144, 'EJE-08', 'Vigente', '🟢', 'Media', '2026-12-31', 'Territorio', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, '[2026-05-08 · Patio Pumakatari de Chasquipampa] La inspección constató que el servicio opera al ~46% (64 de 140 buses) porque los buses no salen con menos de medio tanque y falta presupuesto de combustible: «tenemos con esa flota hasta finales para operar... el problema son los surtidores... no es presupuesto todavía». Refuerza la necesidad de reprogramar el presupuesto.');
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C004', 'Ejecutar la agenda de julio con 165 actividades de reactivación económica', 'Desarrollar las 165 actividades de la agenda de julio orientadas a la reactivación económica de la ciudad y a la conmemoración de los 217 años de la Revolución Paceña, con epicentro el 14, 15 y 16 de julio en la calle Jaén.', 5, 'EJE-04', 'Vigente', '🔴', 'Alta', '2026-07-31', 'Gabinete', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C003', 'Preparar los museos de la calle Jaén como salas de exhibición para las fiestas julias', 'Preparar y mejorar la exhibición de los museos de la calle Jaén (Costumbrista, Litoral, Metales Preciosos, Casa de Murillo) como salas principales de la historia y cultura de la ciudad para recibir a los visitantes durante el mes de julio.', 84, 'EJE-06', 'Vigente', '🔴', 'Media', '2026-07-01', 'Territorio', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C002', 'Crear un nuevo museo patrimonial en el centenario del Palacio Consistorial', 'Habilitar un nuevo museo de cultura y patrimonio cultural sobre la historia de la ciudad de La Paz, con montaje museográfico, curaduría y conservación de bienes culturales en este edificio patrimonial del centro histórico que cumple 100 años. Actividad cultural de las fiestas julias trabajada con la Secretaría de Ciudad Cultural, la Dirección de Culturas y los museos municipales, exhibiendo piezas patrimoniales hoy no exhibidas.', 89, 'EJE-06', 'Vigente', '🔴', 'Media', '2026-07-16', 'Territorio', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C001', 'Realizar la Larga Noche de Museos el 11 de julio de 2026', 'Llevar a cabo la Larga Noche de Museos en la ciudad de La Paz el 11 de julio, actividad cultural postergada por el conflicto, como instrumento de reactivación económica y encuentro de las familias paceñas. Coordinación con los museos de la calle Jaén y el sector cultural y artístico.', 88, 'EJE-06', 'Vigente', '🔴', 'Alta', '2026-07-11', 'Territorio', 'Calle Jaén, La Paz (centro histórico)', '-16.4954,-68.1356', 0, NULL);
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C063', 'Gestionar ante el gobierno nacional la ampliación del feriado paceño', 'El alcalde anunció que pondrá a consideración del gobierno nacional y del sector privado la ampliación del feriado (feriado largo) para impulsar el turismo interno hacia La Paz y reactivar la economía del comercio, artesanos, restaurantes y hoteles, golpeada tras los 53 días de bloqueo.
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C062', 'Atender problema de desplazamiento y planos en Callapa', 'Dirigente vecinal expuso que Callapa tiene un problema de desplazamiento de suelo: los planos aprobados en 2016 quedaron desfasados por asentamientos del terreno (variación entre calles), lo que impide a muchos vecinos instalar servicios básicos. Pidió coordinar una solución; el alcalde se comprometió a verlo con su equipo. Ubicación: zona de Callapa, macrodistrito San Antonio (panadería de Alejandro Chiri).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C061', 'Revisar caso de vecino de Callapa sin conexión de gas', 'Un vecino de Callapa denunció que su trámite de instalación de gas domiciliario está trancado/observado (argumentan que su lote está sobre el río, aunque su plano aprobado no muestra afectación; los vecinos colindantes sí tienen gas). El alcalde se comprometió a ver el caso personalmente y dar la instrucción al equipo (unidad de redes) para destrabarlo. Ubicación: zona de Callapa, macrodistrito San Antonio (panadería de Alejandro Chiri).
insert into tarea (codigo, titulo, descripcion, responsable_unidad_id, eje_codigo, estado, semaforo, prioridad_declarada, plazo, origen, lugar_captura, coordenadas, avance_fisico, entrada_texto) values ('C060', 'Acelerar la ejecución del POA en todos los barrios', 'El alcalde comprometió ante las juntas vecinales que ningún barrio ni vecino se quedará sin la ejecución de su POA, y que se está acelerando todo el proceso para ejecutar de inmediato los POA pendientes, pese a la escasez de recursos de la gestión.
